function todayValue(){const d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');}
const S={session:null,role:'Member',assignment:null,page:'Home',authMode:'login',branches:[],profiles:[],financials:[],payments:[],paymentsReady:false,paymentsError:'',paymentPages:{},cashierSearch:'',cashierSearchBy:'any',cashierPage:1,cashierMemberId:'',requests:[],content:[],audit:[],team:[],applications:[],me:null,scope:'all',search:'',pageNumber:1,error:'',busy:false,photoUrl:'',directoryDistrict:null,activityPages:{},memberDistrict:'all',searchBy:'any',memberSort:'name',reports:[],reportTypes:[],reportEvents:[],reportsReady:false,reportsError:'',workReports:[],workReportEvents:[],reportFrequency:'Daily',reportOn:todayValue(),reportTab:'Analytics',reportDistrict:'all',reportBranch:'all',branchSummaryDistrict:null,branchTransactionsDistrict:null,staffInvite:null,staffInviteError:'',staffSignupPending:false,staffInvites:[],staffInvitesError:'',staffApplicationPage:1,financeSearch:'',financeStatus:'all',financePage:1,reportYear:String(new Date().getFullYear()),reportStatus:'all',reportPage:1,auditRole:'all',auditSort:'newest',teamTab:'Directory',teamRoleTab:'Admin',teamDistrict:'all',teamBranch:'all',teamSearch:'',teamPage:1};
const memberNav=[['Home','home'],['Accounts','wallet'],['Community','megaphone'],['Activity','clock'],['Profile','user']];
const cmsNav=[['Overview','grid'],['Members','users'],['Approvals','shield'],['Financial sync','wallet'],['Reports','file'],['Content','megaphone'],['Activity','clock'],['Team','users'],['Settings','shield']];
const $=id=>document.getElementById(id);const today=()=>{const d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');};
const bn=id=>S.branches.find(b=>b.id===id)?.name||'Unassigned';const isStaff=()=>S.role!=='Member';
function storeSession(s){S.session=s;try{s?localStorage.setItem(SESSION_KEY,JSON.stringify(s)):localStorage.removeItem(SESSION_KEY);}catch{}}
async function ensureSession(){if(!S.session)throw Error('Sign in to continue.');if(!S.session.expires_at||S.session.expires_at<Date.now()/1000+60){try{const d=await api('/auth/v1/token?grant_type=refresh_token',{method:'POST',data:{refresh_token:S.session.refresh_token},auth:false});storeSession({...d,expires_at:Date.now()/1000+d.expires_in});}catch(err){storeSession(null);clearData();throw err;}}}
async function api(path,{method='GET',data,auth=true,headers={},raw=false}={}){if(auth)await ensureSession();const h={apikey:C.publishableKey,...headers};if(auth)h.Authorization='Bearer '+S.session.access_token;if(!raw)h['Content-Type']='application/json';const res=await fetch(C.url+path,{method,headers:h,body:data===undefined?undefined:raw?data:JSON.stringify(data),cache:'no-store'});let out=null;try{out=await res.json();}catch{}if(!res.ok){if(['PGRST205','PGRST202','42703'].includes(out?.code))throw Error('Workflow database setup is pending. Run the OCCCI workflow SQL in Supabase.');if(out?.code==='23505'){if(out.message?.includes('occci_cashier_receipt_unique'))throw Error('This receipt number is already recorded in your branch.');if(out.message?.includes('occci_one_dm_per_district'))throw Error('This district already has a DM. Update the existing assignment before assigning a replacement.');if(out.message?.includes('occci_one_bm_per_branch'))throw Error('This branch already has a BM. Update the existing assignment before assigning a replacement.');throw Error('This account number is already assigned. Use the official unique number for this member.');}throw Error(out?.msg||out?.message||out?.error_description||out?.error||'Connection failed. Please try again.');}return out;}
async function allRows(path){const result=[];for(let offset=0;;offset+=500){const page=await api(path+(path.includes('?')?'&':'?')+'limit=500&offset='+offset);result.push(...page);if(page.length<500)return result;}}
const rpc=(name,data)=>api('/rest/v1/rpc/'+name,{method:'POST',data});
function clearData(){for(const key of ['profiles','financials','payments','requests','content','audit','team','applications','reports','reportTypes','reportEvents','workReports','workReportEvents','staffInvites'])S[key]=[];S.paymentsReady=false;S.paymentsError='';S.paymentPages={};S.cashierSearch='';S.cashierSearchBy='any';S.cashierPage=1;S.cashierMemberId='';S.me=null;S.role='Member';S.assignment=null;S.photoUrl='';S.activityPages={};S.auditRole='all';S.auditSort='newest';S.reportsReady=false;S.reportsError='';S.memberDistrict='all';S.searchBy='any';S.memberSort='name';S.reportDistrict='all';S.reportBranch='all';S.branchSummaryDistrict=null;S.branchTransactionsDistrict=null;S.financeSearch='';S.financeStatus='all';S.financePage=1;S.staffSignupPending=false;S.teamTab='Directory';S.teamRoleTab='Admin';S.teamDistrict='all';S.teamBranch='all';S.teamSearch='';S.teamPage=1;}
async function loadBranches(){S.branches=await api('/rest/v1/occci_branches?select=id,name,district,active&order=district,name',{auth:false});}
async function reload(){S.busy=true;S.error='';render();try{await ensureSession();const user=await api('/auth/v1/user');S.session.user=user;S.assignment=(await api('/rest/v1/occci_staff_assignments?user_id=eq.'+user.id+'&select=*'))[0]||null;S.role=S.assignment?.role||'Member';const result=await Promise.all([
 allRows('/rest/v1/occci_profiles?select=*&archived_at=is.null&order=created_at.desc,id'),allRows('/rest/v1/occci_financials?select=*&order=member_id'),allRows('/rest/v1/occci_change_requests?select=*&order=created_at.desc,id'),allRows('/rest/v1/occci_content?select=*&archived_at=is.null&order=updated_at.desc,id'),loadActivity(),allRows('/rest/v1/occci_staff_assignments?select=*&order=user_id'),allRows('/rest/v1/occci_staff_applications?select=*&order=created_at.desc,user_id')]);[S.profiles,S.financials,S.requests,S.content,S.audit,S.team,S.applications]=result;S.me=S.profiles.find(p=>p.id===user.id)||null;if(!S.me)throw Error('Your profile is missing or archived. Contact the cooperative administrator.');if(S.scope!=='all'&&!allowedBranches().some(b=>b.id===S.scope))S.scope='all';await loadReports();await loadStaffInvites();await loadCashierPayments();S.photoUrl='';if(S.me.photo_path){try{S.photoUrl=await signedUrl('occci-avatars',S.me.photo_path);}catch{}}}catch(err){S.error=err.message;}finally{S.busy=false;render();}}
function allowedBranches(){return S.branches.filter(b=>S.role==='Admin'||(S.role==='DM'?b.district===S.assignment?.district:b.id===S.assignment?.branch_id));}
function canReadBranch(id){return Boolean(id)&&allowedBranches().some(b=>b.id===id);}
function canReadProfile(p){const t=directoryAssignment(p);if(S.role==='Admin'||p.id===S.session?.user?.id)return true;if(t?.role==='Admin')return false;if(t?.role==='DM')return S.role==='DM'&&t.district===S.assignment?.district;return canReadBranch(t?.branch_id||p.branch_id);}
function scoped(rows){return rows.filter(r=>{const branch=r.branch_id||(r.action?null:S.profiles.find(p=>p.id===r.member_id)?.branch_id);if(isStaff()&&S.role!=='Admin'&&!(r.full_name?canReadProfile(r):branch?canReadBranch(branch):S.role==='DM'&&r.district===S.assignment?.district))return false;return S.scope==='all'||branch===S.scope;});}
function requestMember(q){const p=S.profiles.find(p=>p.id===q?.member_id);return p&&!p.archived_at&&canReadProfile(p)?p:null;}
function currentMemberRequests(){return scoped(S.requests).filter(q=>requestMember(q));}
function memberApprovalRequest(id){return S.requests.find(q=>q.member_id===id&&q.kind==='Membership approval'&&['Pending','BM approved'].includes(q.status));}
function canSubmitBalances(){return ['Staff','BC','BM'].includes(S.role);}
function branchOptions(selected,all=false,restricted=false){const rows=restricted?allowedBranches():S.branches.filter(b=>b.active);return (all?`<option value="all">All assigned branches</option>`:'')+[...new Set(rows.map(b=>b.district))].sort().map(d=>`<optgroup label="District ${d}">${rows.filter(b=>b.district===d).map(b=>`<option value="${e(b.id)}" ${selected===b.id?'selected':''}>OCCCI ${e(b.name)} Branch</option>`).join('')}</optgroup>`).join('');}
function currentNav(){return isStaff()?cmsNav.map(([n,i])=>S.role==='BC'&&n==='Overview'?['Cashier','wallet']:[n,i]).filter(([n])=>(n!=='Reports'||canUseReports())&&(n!=='Settings'||S.role==='Admin')):S.me?.registration_kind==='Staff'?memberNav.filter(([n])=>n!=='Accounts'):memberNav;}
function pendingMemberProfiles(){return S.profiles.filter(p=>canReadProfile(p)&&!p.archived_at&&p.onboarding_complete!==false&&p.registration_kind!=='Staff'&&!directoryAssignment(p)&&p.membership_status==='Pending verification');}
function approvalPortals(){
 const requests=currentMemberRequests(),members=scoped(pendingMemberProfiles()),items=[
  ...(S.role==='Admin'?[['Staff Applications','shield',S.applications.filter(a=>a.status==='Pending').length]]:[]),
  ['New Members','users',S.role==='DM'?members.filter(p=>{const q=memberApprovalRequest(p.id);return q&&canReview(q);}).length:S.role==='BM'?members.filter(p=>!memberApprovalRequest(p.id)).length:members.length],
  ['Approvals','shield',requests.filter(q=>q.kind==='Profile edit'&&q.status==='Pending'&&(S.role==='Admin'||isOperationalStaff()||canReview(q))).length],
  ['Financial sync','wallet',requests.filter(q=>q.kind==='Financial sync'&&['Pending','BM approved'].includes(q.status)&&(['BM','DM'].includes(S.role)?canReview(q):true)).length]
 ];
 const labels={'Approvals':'Review Staff Edits','Financial sync':'Review Actual Balances'};
 return `<nav class="approval-portals" aria-label="Approval portals">${items.map(([page,i,count])=>`<button type="button" onclick="go('${page}')" ${S.page===page?'aria-current="page"':''}>${icon(i)}<span class="portal-label">${e(labels[page]||page)}</span><span class="portal-count ${count?'has-pending':''}" aria-label="${count} pending">${count}</span></button>`).join('')}</nav>`;
}
function go(page){if(['OCCCI Staff','Staff Applications'].includes(page)){S.teamTab=page==='OCCCI Staff'?'Directory':'Applications';page='Team';}if(page!==S.page&&['Members','New Members','Team'].includes(page)){S.search='';S.searchBy='any';S.memberDistrict='all';}S.page=page;S.pageNumber=1;closeModal();render();window.scrollTo({top:0});}
function render(){document.title='OCCCI Member Connect';const nav=currentNav(),navPage=S.role==='BC'&&['Home','Overview'].includes(S.page)?'Cashier':S.page==='New Members'?'Members':['OCCCI Staff','Staff Applications'].includes(S.page)?'Team':S.page;$('sidebar').innerHTML=`<div class="brand">${logo()}<div><strong>OCCCI</strong><small>${isStaff()?e(roleLabel(S.role))+' workspace':'Member Connect'}</small></div></div><nav class="nav-section">${S.session?nav.map(([n,i])=>button(n==='Reports'&&isOperationalStaff()?'My reports':n,`go('${n}')`,'nav-item '+(navPage===n?'active':''),i)).join(''):''}</nav><div class="sidebar-end">${S.session?button('Sign out','signOut()','','switch'):''}</div>`;
 $('topbar').innerHTML=`<div class="mobile-brand">${logo()}<div><strong>OCCCI</strong><small>Metro Ormoc Community<br>Multi-Purpose Cooperative</small></div></div><div class="desktop-heading"><strong>Metro Ormoc Community Multi-Purpose Cooperative</strong><span>Member Connect</span></div><div class="top-actions">${S.session?`${button('','reload()','icon-btn','switch')}<button class="profile-button" onclick="go('Profile')" aria-label="Your profile"><span class="avatar">${S.photoUrl?`<img src="${e(S.photoUrl)}" alt="Your profile" style="width:100%;height:100%;object-fit:cover">`:avatarArt(S.me?.avatar||'lady')}</span><span class="profile-name"><b>${e(S.me?.full_name||'Member')}</b><small>${e(roleLabel(S.role))} · ${S.role==='Admin'?'All districts':S.role==='DM'?'District '+e(S.assignment?.district):e(bn(S.assignment?.branch_id||S.me?.branch_id))}</small></span></button>${button('','openMenu()','icon-btn menu-button','menu')}`:''}</div>`;
 const showPortals=S.session&&isStaff()&&S.me?.onboarding_complete!==false&&!['Reports','Team','OCCCI Staff','Staff Applications','Content','Activity','Settings'].includes(S.page);$('workspaceTabs').hidden=!showPortals;$('workspaceTabs').innerHTML=showPortals?approvalPortals():'';
 const staffWorkspace=Boolean(S.session&&isStaff());document.querySelector('.workspace')?.classList.toggle('staff-workspace',staffWorkspace);$('demoBar').className=staffWorkspace?'demo-bar workspace-toolbar':'demo-bar';
 $('demoBar').innerHTML=staffWorkspace?`<div class="workspace-context"><span class="demo-label workspace-role" title="${e(roleLabel(S.role))}">${e(S.role==='Staff'?'BS':S.role.toUpperCase())}</span><strong class="workspace-title">Workspace</strong></div>${S.page==='Content'?'':`<label class="workspace-scope" for="workspaceBranch"><span>Branch</span><select id="workspaceBranch" aria-label="Branch workspace" onchange="S.scope=this.value;S.memberDistrict='all';S.reportPage=1;S.pageNumber=1;render()">${branchOptions(S.scope,true,true)}</select></label>`}`:S.session?`<span class="demo-label">${e(roleLabel(S.role).toUpperCase())}</span><span>${S.me?.registration_kind==='Staff'?'Staff application '+e(S.applications.find(a=>a.user_id===S.me.id)?.status||'Pending'):S.me?.membership_status==='Active'?'Verified membership':'Membership verification pending'}</span>`:'<span class="demo-label">MEMBER CONNECT</span><span>Your cooperative, connected.</span>';
 $('bottomnav').innerHTML=S.session?(isStaff()?[[S.role==='BC'?'Cashier':'Overview',S.role==='BC'?'wallet':'grid'],['Members','users'],['Approvals','shield'],['Activity','clock'],['More','menu']]:currentNav()).map(([n,i])=>button(`${icon(i)}<span>${n}</span>`,n==='More'?'openMenu()':`go('${n}')`,n===navPage?'active':'')).join(''):'';
 $('bottomnav').style.display=S.session?'':'none';let html;if(!S.session)html=authView();else if(S.busy&&!S.me)html=empty('Loading your workspace','Connecting to cooperative records.');else if(S.error)html=`<div class="banner"><div><h2>Workspace needs attention</h2><p>${e(S.error)}</p></div>${button('Retry','reload()','primary')}</div>`;else if(S.staffInvite)html=staffInviteView();else if(S.me?.onboarding_complete===false)html=onboardingView();else html=isStaff()?cmsView():memberView();$('main').innerHTML=html;document.querySelectorAll('select[aria-label="Branch workspace"]').forEach(n=>n.value=S.scope);}
function openModal(title,body,{className='',header=''}={}){$('modal').className=className;$('modalContent').innerHTML=`<div class="dialog-head">${header||`<h2 id="dialogTitle">${e(title)}</h2>`}${button('','closeModal()','icon-btn','close')}</div><div class="dialog-body"><p id="actionMessage" role="alert" aria-live="polite" class="form-error"></p>${body}</div>`;if(!$('modal').open)$('modal').showModal();}
let recordLogReturn=null;
function closeModal(){const secret=$('generatedStaffCode');if(secret)secret.value='';recordLogReturn=null;if($('modal').open)$('modal').close();}function toast(text){$('toast').textContent=text;$('toast').hidden=false;setTimeout(()=>$('toast').hidden=true,4000);}
function openMenu(){openModal('Your workspace',`<div class="mobile-menu">${currentNav().map(([n,i])=>button(n,`go('${n}')`,'',i)).join('')}</div>${button('My profile',"go('Profile')",'outline','user')}${button('Sign out','signOut()','secondary','switch')}`);}
function field(label,name,value='',type='text',required=true){return `<label>${label}<input name="${name}" type="${type}" value="${e(value)}" ${required?'required':''} ${type==='number'?'min="0" step="0.01"':''} maxlength="${['first_name','last_name','middle_name'].includes(name)?50:name==='contact_number'?30:name==='address'?500:150}"></label>`;}
function authView(){if(S.staffInvite)return staffInviteView();const reg=S.authMode==='register';return `<section class="card auth-card"><div class="card-head"><div><h1>${reg?'Become connected':'Welcome to OCCCI'}</h1><p class="muted">${reg?'Register as a Cooperative Member.':'Sign in to your member or staff workspace.'}</p></div></div><div class="tabs">${button('Sign in',"S.authMode='login';render()",!reg?'active':'')}${button('Register',"S.authMode='register';render()",reg?'active':'')}</div>${S.error?`<p role="alert" class="form-error">${e(S.error)}</p>`:''}<button type="button" class="google-signin outline" onclick="googleSignIn(this)"><span class="google-mark" aria-hidden="true">G</span>Continue with Google</button><p class="auth-divider">or use email</p><form onsubmit="event.preventDefault();submitAuth(this)"><div class="form-grid">${reg?`${memberProfileFields()}`:''}${field('Email','email','','email')}<label>Password<input name="password" type="password" minlength="8" autocomplete="${reg?'new-password':'current-password'}" required></label></div><p class="smalltext">${reg?'Confirm your email, then sign in. Your branch will verify your cooperative membership.':'Your access is determined by your cooperative assignment.'}</p><button type="submit" class="primary">${reg?'Create account':'Sign in'}</button><p id="authMessage" role="status" aria-live="polite"></p></form></section>`;}
function memberProfileFields(){return `${signupKindPicker()}${field('Last name','last_name')}${field('First name','first_name')}${field('Middle name (optional)','middle_name','','text',false)}${field('Contact number','contact_number','','tel')}<label class="full">Complete address<textarea name="address" maxlength="500" required autocomplete="street-address"></textarea></label><label>District<select name="district" onchange="registrationBranches(this.value)" required>${[...new Set(S.branches.filter(b=>b.active).map(b=>b.district))].sort().map(d=>`<option value="${d}">District ${d}</option>`).join('')}</select></label><label>Branch<select id="registerBranch" name="branch_id" required>${registrationOptions(S.branches.find(b=>b.active)?.district)}</select></label>${avatarPicker()}<label class="full">Profile photo (optional)<input type="file" name="photo" accept="image/*"><span class="hint">Use an avatar if your iPhone or iPad cannot upload the photo. JPG/PNG photos are supported; photos from other formats will be converted when possible.</span></label>`;}
function signupKindPicker(){return `<div class="registration-type full"><span class="iconbox">${icon('user')}</span><div><strong>Cooperative Member</strong><p class="smalltext">Register for membership and personal account services.</p></div><input type="hidden" name="registration_kind" value="Member"></div>`;}

function registrationOptions(d){return S.branches.filter(b=>b.active&&b.district===Number(d)).map(b=>`<option value="${e(b.id)}">${e(b.name)}</option>`).join('');}function registrationBranches(d){$('registerBranch').innerHTML=registrationOptions(d);}
async function normalizePhoto(file){if(file.size>5*1024*1024)throw Error('Photo is larger than 5 MB. Choose a smaller photo or use an avatar.');return new Promise((resolve,reject)=>{const url=URL.createObjectURL(file),img=new Image();img.onload=()=>{const canvas=document.createElement('canvas');const scale=Math.min(1,900/Math.max(img.width,img.height));canvas.width=Math.round(img.width*scale);canvas.height=Math.round(img.height*scale);canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);URL.revokeObjectURL(url);canvas.toBlob(b=>b?resolve(b):reject(Error('Use a temporary avatar; this photo cannot be converted.')),'image/jpeg',.85);};img.onerror=()=>{URL.revokeObjectURL(url);reject(Error('Your device cannot open this photo. You can continue with a temporary avatar.'));};img.src=url;});}
let pendingPhoto=null;

async function submitAuth(form){const btn=form.querySelector('button[type=submit],button:not([type])');const buttonLabel=btn?.textContent;if(btn)btn.disabled=true;const f=new FormData(form);try{if(S.authMode==='register'){const branch=S.branches.find(b=>b.id===f.get('branch_id')&&b.district===Number(f.get('district'))&&b.active);if(!branch)throw Error('Choose a branch in your district.');const data=Object.fromEntries(['last_name','first_name','middle_name','contact_number','address','avatar'].map(k=>[k,String(f.get(k)||'').trim()]));if(data.contact_number.length<7||data.address.length<5)throw Error('Enter a complete address and contact number.');data.branch_id=branch.id;data.district=branch.district;data.registration_kind='Member';pendingPhoto=null;const file=f.get('photo');if(file?.size){try{pendingPhoto=await normalizePhoto(file);}catch(err){$('authMessage').textContent=err.message+' Registering with your selected avatar.';}}const result=await api('/auth/v1/signup',{method:'POST',auth:false,data:{email:f.get('email'),password:f.get('password'),data}});if(result.access_token){storeSession({...result,expires_at:Date.now()/1000+result.expires_in});await reload();if(pendingPhoto)await uploadPhotoBlob(pendingPhoto);}else{$('authMessage').textContent='Check your email to confirm your account, then return to sign in. You can upload your photo after signing in.';form.reset();}}
 else{const result=await api('/auth/v1/token?grant_type=password',{method:'POST',auth:false,data:{email:f.get('email'),password:f.get('password')}});storeSession({...result,expires_at:Date.now()/1000+result.expires_in});S.page='Home';await reload();if(isStaff()){S.page='Overview';render();}if(pendingPhoto){try{await uploadPhotoBlob(pendingPhoto);}catch(err){toast(err.message);}pendingPhoto=null;}}}catch(err){const node=$('authMessage');if(node)node.textContent=err.message;else{S.error=err.message;render();}}finally{btn.disabled=false;}}
async function signOut(){try{await api('/auth/v1/logout',{method:'POST'});}catch{}storeSession(null);clearData();S.error='';S.page='Home';S.scope='all';closeModal();render();}
async function upload(bucket,file){const extension=bucket==='occci-avatars'?(file.type==='image/png'?'png':'jpg'):(file.name?.split('.').pop()?.replace(/[^a-zA-Z0-9]/g,'').slice(0,16)||'bin');const path=S.session.user.id+'/'+crypto.randomUUID()+'.'+extension;await api('/storage/v1/object/'+bucket+'/'+path,{method:'POST',data:file,raw:true,headers:{'Content-Type':file.type||'application/octet-stream'}});return path;}
async function signedUrl(bucket,path){const result=await api('/storage/v1/object/sign/'+bucket+'/'+path,{method:'POST',data:{expiresIn:300}});return C.url+'/storage/v1'+result.signedURL;}
async function uploadPhotoBlob(blob){const path=await upload('occci-avatars',blob);await rpc('occci_set_photo',{photo:path});pendingPhoto=null;await reload();toast('Profile photo updated.');}
async function changePhoto(form){const btn=form.querySelector('[type=submit]');btn.disabled=true;try{const file=new FormData(form).get('photo');await uploadPhotoBlob(await normalizePhoto(file));}catch(err){$('actionMessage').textContent=err.message;}finally{btn.disabled=false;}}
function profileView(){const p=S.me;return heading('My profile','Your cooperative member details.')+`<section class="card"><div class="profile-summary"><span class="avatar">${S.photoUrl?`<img src="${e(S.photoUrl)}" alt="Profile photo" style="width:100%;height:100%;object-fit:cover">`:avatarArt(p.avatar)}</span><div><h2>${e(p.full_name)}</h2><p>${e(directoryMembershipStatus(p))} · ${e(roleLabel(S.role))}</p></div></div><dl class="details-list">${p.employee_id?detail('Employee Number / ID',e(p.employee_id)):detail('Account number',e(p.account_number||'Awaiting approval'))}${detail('District',S.role==='Admin'?'All districts':S.role==='DM'?'District '+S.assignment?.district:S.branches.find(b=>b.id===(S.assignment?.branch_id||p.branch_id))?.district?'District '+S.branches.find(b=>b.id===(S.assignment?.branch_id||p.branch_id)).district:'Awaiting assignment')}${detail('Branch',e(S.role==='Admin'?'All branches':S.role==='DM'?'All branches in District '+S.assignment?.district:bn(S.assignment?.branch_id||p.branch_id)))}${detail('Email',e(S.session.user.email))}${detail('Contact',e(p.contact_number||'Not yet recorded'))}${detail('Address',e(p.address||'Not yet recorded'))}</dl>${S.role==='Member'&&p.registration_kind!=='Staff'?memberProfileBalances():''}${isOperationalStaff()?button('My work reports',"go('Reports')",'primary','file'):''}${button('Upload profile photo','photoDialog()','outline','user')}<p class="smalltext">To correct member information, contact your branch staff. Every approved correction is recorded in your activity log.</p></section>`;}
function photoDialog(){openModal('Profile photo',`<form onsubmit="event.preventDefault();changePhoto(this)"><label>Photo<input type="file" name="photo" accept="image/*" required></label><p class="hint">If your device cannot upload a photo, your temporary avatar stays in place.</p><button class="primary" type="submit">Upload photo</button></form>`);}
function memberView(){if(S.me.registration_kind==='Staff'&&['Home','Accounts'].includes(S.page))return staffApplicantView();if(S.page==='Profile')return profileView();if(S.page==='Activity')return auditView(S.audit.filter(a=>a.member_id===S.me.id));if(S.page==='Community')return contentView(false);const f=S.financials.find(f=>f.member_id===S.me.id);return heading(S.page==='Accounts'?'My accounts':'Welcome, '+e(S.me.first_name||S.me.full_name),`${e(bn(S.me.branch_id))} branch · ${e(S.me.account_number||'Account number pending')}`)+memberFinancialDashboard(f)+memberFinanceDetails(f)+(S.page==='Home'?'<section class="spacer">'+contentView(false,false)+'</section>':'');}
function memberProfileBalances(){const f=S.financials.find(f=>f.member_id===S.me.id);return `<section class="profile-financial-summary"><div class="card-head"><h2>Member balances</h2>${f?`<span class="smalltext">As of ${e(f.as_of)}</span>`:''}</div>${f?`<dl class="finance-record-values">${detail('Savings balance',money(f.savings))}${detail('Share capital',e(shareCapitalValue(f)))}${detail('Loan balance',money(f.loan_balance))}${detail('Loan status',e(f.loan_status))}</dl>`:'<p class="hint">No financial records yet. Update and verification required.</p>'}</section>`;}
function staffApplicantView(){const a=S.applications.find(a=>a.user_id===S.me.id);return heading('Your OCCCI Staff application','CMS access becomes available after cooperative Admin approval.')+`<section class="card"><div class="card-head"><h2>${e(S.me.full_name)}</h2>${statusPill(a?.status||'Awaiting review')}</div><dl class="details-list">${detail('Employee Number / ID',e(S.me.employee_id||'Awaiting Admin verification'))}${detail('Position',e(a?.assigned_role?STAFF_ROLE_LABELS[a.assigned_role]:'Admin will assign after review'))}${a?.assigned_role==='DM'?detail('District','District '+a.district):a?.branch_id?detail('Branch',e(bn(a.branch_id))):''}</dl><p>${e(a?.review_note||'The cooperative Admin will verify your employee ID, review your application and assign your position.')}</p>${button('Refresh status','reload()','primary')}${button('My profile',"go('Profile')",'outline')}</section>`;}
function scheduleView(rows){return rows?.length?`<div class="schedule-list">${rows.map(x=>`<div class="transaction-row"><div><h3>${e(financeDate(x.date))}</h3><small>${e(x.status||'Scheduled')}${installmentPaid(x)>0&&installmentRemaining(x)>0?' · Partly paid':''}</small></div><span class="scheduled-payment-amount"><strong>${money(x.amount)}</strong>${x.status==='Paid'?'<small>Paid in full</small>':x.status==='Cancelled'?'':`<small>${money(installmentRemaining(x))} remaining</small>`}</span></div>`).join('')}</div>`:empty('No payment schedule','A schedule will appear when your branch syncs it.');}
function metric(label,value,sub){return `<section class="card admin-metric"><p class="eyebrow">${label}</p><div class="big-number">${value}</div><p class="smalltext">${sub}</p></section>`;}
function cmsView(){if(S.page==='Cashier'||S.role==='BC'&&['Overview','Home'].includes(S.page))return cashierView();if(S.page==='Profile')return profileView();if(S.page==='Settings')return staffSettingsView();if(['Members','New Members'].includes(S.page))return membersView();if(['OCCCI Staff','Staff Applications'].includes(S.page)){S.teamTab=S.page==='OCCCI Staff'?'Directory':'Applications';return teamView();}if(S.page==='Approvals')return approvalsView();if(S.page==='Financial sync')return financialView();if(S.page==='Reports')return reportsView();if(S.page==='Content')return contentView(true);if(S.page==='Activity')return auditView(S.audit);if(S.page==='Team')return teamView();if(S.page==='Branches')return branchesView();const profiles=scoped(S.profiles).filter(p=>!p.archived_at&&p.registration_kind!=='Staff'&&!directoryAssignment(p)),requests=currentMemberRequests();return heading('Cooperative workspace',`${e(roleLabel(S.role))} · ${S.role==='DM'?'District '+S.assignment.district:S.role==='Admin'?'All districts':e(bn(S.assignment.branch_id))+' branch'}`)+`<div class="grid four">${metric('Members',profiles.filter(p=>p.membership_status==='Active').length,'Approved memberships')}${metric('New registrations',profiles.filter(p=>p.membership_status==='Pending verification').length,'Awaiting account number')}${metric('Edit requests',requests.filter(q=>q.kind==='Profile edit'&&['Pending','BM approved'].includes(q.status)).length,'BM / DM approval workflow')}${metric('Financial sync',requests.filter(q=>q.kind==='Financial sync'&&['Pending','BM approved'].includes(q.status)).length,'BM screening then DM approval')}</div><p class="smalltext spacer">Membership, edits, document submissions and approvals are recorded in the CMS and member activity logs.</p>`;}
function normalized(text){return String(text||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]/g,'');}
function editDistance(a,b){let prev=Array.from({length:b.length+1},(_,i)=>i),older=null;for(let i=1;i<=a.length;i++){const row=[i];for(let j=1;j<=b.length;j++){row[j]=Math.min(row[j-1]+1,prev[j]+1,prev[j-1]+(a[i-1]!==b[j-1]));if(i>1&&j>1&&a[i-1]===b[j-2]&&a[i-2]===b[j-1])row[j]=Math.min(row[j],older[j-2]+1);}older=prev;prev=row;}return prev[b.length];}
function memberMatches(p,query){const q=String(query).trim();if(!q)return true;if(p.account_number?.toLowerCase()===q.toLowerCase()||p.employee_id?.toLowerCase()===q.toLowerCase())return true;const key=normalized(q),name=normalized(p.full_name);if(name.includes(key))return true;if(key.length<3)return false;const words=String(p.full_name).split(/\s+/).map(normalized);return words.some(w=>editDistance(w,key)<=Math.max(1,Math.floor(key.length/4)))||[...key].every((ch,index,all)=>{let pos=-1;for(const c of all.slice(0,index+1)){pos=name.indexOf(c,pos+1);if(pos<0)return false;}return true;});}
function directoryAssignment(p){return S.team.find(t=>t.user_id===p.id&&['Admin','DM','BM','Staff','BC'].includes(t.role));}
function directoryPosition(p){return ({Admin:'Admin',DM:'District Manager (DM)',BM:'Branch Manager (BM)',Staff:'Branch Staff (BS)',BC:'Branch Cashier (BC)'})[directoryAssignment(p)?.role]||'Member';}
function directoryGroup(p){const t=directoryAssignment(p);if(t?.role==='Admin')return {key:'global',title:'Head office · all districts'};if(t?.role==='DM')return {key:'district:'+t.district,title:'District '+t.district+' management'};const branch=t?.branch_id||p.branch_id;return {key:'branch:'+branch,title:bn(branch)+' branch'};}
function isStaffDirectory(){return S.page==='OCCCI Staff'||(S.page==='Team'&&S.teamTab==='Directory');}
function directoryRows(){const newMembers=S.page==='New Members',staffDirectory=isStaffDirectory();return S.profiles.filter(p=>{
 const t=directoryAssignment(p);if(p.archived_at||!canReadProfile(p))return false;
 if(staffDirectory?!t:Boolean(t)||p.registration_kind==='Staff')return false;
 if(newMembers&&(p.onboarding_complete===false||p.membership_status!=='Pending verification'))return false;
 const branch=t?.branch_id||p.branch_id,d=t?.role==='DM'?t.district:S.branches.find(b=>b.id===branch)?.district;
 if(S.scope!=='all'&&!(t?.role==='Admin'||(t?.role==='DM'?t.district===S.branches.find(b=>b.id===S.scope)?.district:branch===S.scope)))return false;
 if(S.memberDistrict!=='all'&&t?.role!=='Admin'&&d!==Number(S.memberDistrict))return false;
 const q=S.search.trim().toLowerCase();if(!q)return true;
 if(S.searchBy==='id')return (staffDirectory?p.employee_id:p.account_number)?.toLowerCase()===q||p.id?.toLowerCase()===q;
 if(S.searchBy==='name')return memberMatches({...p,account_number:null,employee_id:null},q);
 if(S.searchBy==='branch')return bn(branch).toLowerCase().includes(q);
 if(S.searchBy==='district')return ('district '+d).includes(q)||String(d)===q;
 return memberMatches(p,q)||p.id?.toLowerCase()===q;
 }).sort((a,b)=>{if(S.memberSort==='id'){const left=directoryIdentifier(a),right=directoryIdentifier(b);return (!left)-(!right)||left.localeCompare(right)||a.full_name.localeCompare(b.full_name);}if(S.memberSort==='district')return (directoryAssignment(a)?.district||S.branches.find(b=>b.id===(directoryAssignment(a)?.branch_id||a.branch_id))?.district||0)-(directoryAssignment(b)?.district||S.branches.find(b=>b.id===(directoryAssignment(b)?.branch_id||b.branch_id))?.district||0)||a.full_name.localeCompare(b.full_name);if(S.memberSort==='branch')return directoryGroup(a).title.localeCompare(directoryGroup(b).title)||a.full_name.localeCompare(b.full_name);return a.full_name.localeCompare(b.full_name);});}
function directoryMembershipStatus(p){return directoryAssignment(p)?'Active':p.membership_status==='Pending verification'?(memberApprovalRequest(p.id)?'Awaiting DM approval':'Awaiting BM screening'):p.membership_status;}
function directoryIdentifier(p){return directoryAssignment(p)?p.employee_id||'':p.account_number||'';}
function memberFilterOptions(options,value){return options.map(([v,label])=>`<option value="${e(v)}" ${String(value)===String(v)?'selected':''}>${e(label)}</option>`).join('');}
function memberDistrictChanged(value){S.memberDistrict=value;if(value!=='all'&&S.scope!=='all'&&S.branches.find(b=>b.id===S.scope)?.district!==Number(value))S.scope='all';S.pageNumber=1;render();}
function membersView(withHeading=true){const rows=directoryRows(),size=12,newMembers=S.page==='New Members',staffDirectory=isStaffDirectory();S.pageNumber=Math.min(S.pageNumber,Math.max(1,Math.ceil(rows.length/size)));const show=rows.slice((S.pageNumber-1)*size,S.pageNumber*size),branches=allowedBranches().filter(b=>S.memberDistrict==='all'||b.district===Number(S.memberDistrict));return (withHeading?heading(newMembers?'New Members':staffDirectory?'OCCCI Staff':'Members',newMembers?'BM screens new members; the assigned DM approves and activates membership.':staffDirectory?'Approved cooperative personnel, grouped by their assigned workplace.':'Cooperative members, grouped by branch.'):'')+`<section class="card people-directory"><div class="member-filters"><label>Search by<select onchange="S.searchBy=this.value;S.pageNumber=1;render()">${memberFilterOptions([['any','Name / ID'],['name','Name'],['id',staffDirectory?'Exact employee / user ID':'Exact account / user ID'],['district','District'],['branch','Branch']],S.searchBy)}</select></label><label class="member-search">Search<input type="search" placeholder="${S.searchBy==='id'?(staffDirectory?'Exact employee number or user ID':'Exact account number or user ID'):staffDirectory?'Search OCCCI Staff':'Search members'}" value="${e(S.search)}" oninput="S.search=this.value;S.pageNumber=1;refreshMemberList()"></label><label>District<select onchange="memberDistrictChanged(this.value)">${memberFilterOptions([['all','All assigned districts'],...[...new Set(allowedBranches().map(b=>b.district))].sort().map(d=>[d,'District '+d])],S.memberDistrict)}</select></label><label>Branch<select onchange="S.scope=this.value;S.pageNumber=1;render()">${memberFilterOptions([['all','All assigned branches'],...branches.map(b=>[b.id,b.name])],S.scope)}</select></label><label>Sort by<select onchange="S.memberSort=this.value;S.pageNumber=1;render()">${memberFilterOptions([['name','Name'],['id',staffDirectory?'Employee number':'Account number'],['district','District'],['branch','Branch']],S.memberSort)}</select></label></div>${newMembers?'<p class="hint">Showing members awaiting verification.</p>':''}<div id="memberList">${memberList(show,rows.length)}</div></section>`;}

function refreshMemberList(){const rows=directoryRows();$('memberList').innerHTML=memberList(rows.slice(0,12),rows.length);}
function memberList(rows,total){const groups=new Map();for(const p of rows){const g=directoryGroup(p);if(!groups.has(g.key))groups.set(g.key,{...g,people:[]});groups.get(g.key).people.push(p);}return `<p class="directory-count">${total} matching ${total===1?'person':'people'}</p>${[...groups.values()].map(g=>`<section class="people-group"><div class="people-group-heading"><h3>${e(g.title)}</h3><span>${g.people.length} ${g.people.length===1?'person':'people'}</span></div><ul class="people-list">${g.people.map(p=>`<li class="directory-person-row"><span class="avatar">${avatarArt(p.avatar)}</span><div class="directory-person-info"><h3>${e(p.full_name)}${directoryAssignment(p)?`<span class="directory-name-position"> · ${e(directoryPosition(p))}</span>`:''}</h3><p>${e(directoryIdentifier(p)||(directoryAssignment(p)?'Employee ID not recorded':'ID not assigned'))}</p>${directoryAssignment(p)?`<small class="directory-email">${e(p.email||'Email not recorded')}</small>`:''}</div><div class="directory-person-meta">${directoryAssignment(p)?'':`<span class="directory-position">${e(directoryPosition(p))}</span>`}<span class="directory-membership">${e(directoryMembershipStatus(p))}</span></div>${button('View',`memberDialog('${p.id}')`,'small secondary','eye')}</li>`).join('')}</ul></section>`).join('')||empty('No matching people','Choose a branch, change the filter or try fewer characters.')}<div class="pagination"><span>Page ${S.pageNumber} of ${Math.max(1,Math.ceil(total/12))}</span><div class="flex">${button('Previous',"S.pageNumber=Math.max(1,S.pageNumber-1);render()",'outline small')}${button('Next',"S.pageNumber++;render()",'outline small')}</div></div>`;}
function memberDialog(id){
 const p=S.profiles.find(p=>p.id===id);if(!p||p.archived_at||!canReadProfile(p))return;
 const assignment=directoryAssignment(p),activity=S.audit.filter(a=>a.member_id===id),isEmployee=Boolean(assignment)||p.registration_kind==='Staff';
 const header=`<div class="member-record-identity"><span class="avatar">${avatarArt(p.avatar||'man')}</span><div class="member-record-name"><span class="member-record-eyebrow">${isEmployee?'OCCCI personnel':'Member record'}</span><h2 id="dialogTitle">${e(p.full_name)}</h2><div class="member-record-meta"><span>${e(directoryPosition(p))}</span>${statusPill(directoryMembershipStatus(p))}</div></div></div>`;
 openModal(p.full_name,`<dl class="details-list member-record-details">${isEmployee?detail('Employee Number / ID',e(p.employee_id||'Not yet recorded')):detail('Account number',e(p.account_number||'Awaiting assignment'))}${detail('Contact number',e(p.contact_number||'Not yet recorded'))}${isEmployee?detail('Email',e(p.email||'Not yet recorded')):''}${detail(assignment?'Workplace':'Branch',e(assignment?directoryGroup(p).title:bn(p.branch_id)))}${detail('Complete address',e(p.address||'Not yet recorded'))}</dl><section class="member-record-controls" aria-labelledby="memberActionsTitle"><h3 id="memberActionsTitle">Manage record</h3><div class="member-record-actions">${isEmployee?`${S.role==='Admin'?button('Edit team assignment',`teamDialog('${id}')`,'outline','users'):''}${button('Record update logs',`memberActivityDialog('${id}')`,'outline','clock')}`:`${p.membership_status==='Pending verification'?(memberApprovalRequest(id)?button(S.role==='DM'&&canReview(memberApprovalRequest(id))?'Review membership':'View membership screening',`requestDialog('${memberApprovalRequest(id).id}')`,S.role==='DM'?'primary':'outline','shield'):S.role==='BM'?button('Screen for DM approval',`membershipDialog('${id}')`,'primary','check'):''):''}${button(isOperationalStaff()?'Request information edit':'Edit member information',isOperationalStaff()?`editPermissionDialog('${id}')`:`editDialog('${id}')`,'outline','edit')}${['Staff','BC','BM','DM'].includes(S.role)?button('Assign / update ID number',`accountDialog('${id}')`,'outline','card'):''}${button('Record update logs',`memberActivityDialog('${id}')`,'outline','clock')}${canSubmitBalances()&&p.membership_status==='Active'?button('Submit actual balances',`syncDialog('${id}')`,'outline','wallet'):''}${S.role==='Admin'?button('Archive member',`removeDialog('Member','${id}')`,'danger','file'):''}`}</div></section><section class="member-record-activity" aria-labelledby="memberActivityTitle"><button type="button" id="memberActivityToggle" class="outline member-activity-toggle" aria-expanded="false" aria-controls="memberActivityDetails" onclick="toggleMemberActivity(this)">${icon('clock')}<span id="memberActivityTitle" class="member-activity-toggle-label">Member activity</span><span class="member-activity-count">${activity.length} ${activity.length===1?'entry':'entries'}</span><span class="activity-chevron">${icon('down')}</span></button><div id="memberActivityDetails" class="member-activity-details" hidden>${auditRows(activity,'member:'+id)}</div></section>`,{className:'member-details-dialog',header});
}
function toggleMemberActivity(button){const panel=$(button.getAttribute('aria-controls'));if(!panel)return;const expanded=button.getAttribute('aria-expanded')!=='true';button.setAttribute('aria-expanded',String(expanded));panel.hidden=!expanded;}
function recordLogButton(id){return `<div class="form-utility"><button type="button" class="outline small" onclick="memberActivityDialog('${id}',true)">${icon('clock')} Record update logs</button></div>`;}
function memberActivityDialog(id,fromForm=false){if(fromForm){recordLogReturn=document.createDocumentFragment();while($('modalContent').firstChild)recordLogReturn.appendChild($('modalContent').firstChild);}const p=S.profiles.find(p=>p.id===id);openModal('Record update logs',`<p class="smalltext">${e(p?.full_name||'Member')} · ${e(p?.account_number||'ID pending')}</p>${recordLogReturn?'<button type="button" class="outline small" onclick="returnToRecordForm()">Back to record form</button>':button('Back to member',`memberDialog('${id}')`,'outline small')}<div class="spacer">${auditRows(S.audit.filter(a=>a.member_id===id),'record:'+id)}</div>`);}
function returnToRecordForm(){if(!recordLogReturn)return;$('modalContent').replaceChildren(recordLogReturn);recordLogReturn=null;}
function membershipDialog(id){const p=S.profiles.find(p=>p.id===id);if(S.role!=='BM'||!p||!canReadBranch(p.branch_id)){toast('The assigned Branch Manager screens new members.');return;}const q=memberApprovalRequest(id);if(q)return requestDialog(q.id);openModal('BM membership screening',`<form onsubmit="event.preventDefault();handleCmsAction(this,'membership','${id}')"><p class="smalltext">${e(p.full_name)} · ${e(bn(p.branch_id))}</p><label>Official ID / account number<input name="account" value="${e(p.account_number||'')}" maxlength="40" pattern="[A-Za-z0-9][A-Za-z0-9/\-]{2,39}" required></label><label class="spacer">Reason / Comments / Notes<textarea name="reason" minlength="3" maxlength="5000" required></textarea></label><p class="hint">Saving sends the screened application to this branch’s District Manager. Membership and the official account number become active after DM approval.</p><button class="primary" type="submit">Save and send to DM</button></form>`);}
function editDialog(id,requestId=''){if(isOperationalStaff()&&!requestId)return editPermissionDialog(id);const p=S.profiles.find(p=>p.id===id);openModal('Member information edit',`<form onsubmit="event.preventDefault();handleCmsAction(this,'edit','${id}','${requestId}')">${recordLogButton(id)}<div class="form-grid">${field('Last name','last_name',p.last_name)}${field('First name','first_name',p.first_name)}${field('Middle name','middle_name',p.middle_name,'text',false)}${field('Contact number','contact_number',p.contact_number,'tel')}<label class="full">Complete address<textarea name="address" maxlength="500" required>${e(p.address)}</textarea></label><label>Status<select name="membership_status">${['Active','Suspended','Pending verification'].map(v=>`<option ${v===p.membership_status?'selected':''}>${v}</option>`).join('')}</select></label>${avatarPicker(p.avatar)}<label class="full">Reason / Comments / Notes<textarea name="reason" minlength="3" required></textarea></label></div><p class="smalltext">${['DM','BM','Admin'].includes(S.role)?'Your authorized change will be applied and logged.':'BM or DM approval was granted. This permission applies once; your changes will be recorded.'}</p><button class="primary" type="submit">${['DM','BM','Admin'].includes(S.role)?'Save and record change':'Save approved edit'}</button></form>`);}
function syncDialog(id){const p=S.profiles.find(p=>p.id===id);if(!canSubmitBalances()||!p||!canReadBranch(p.branch_id)){toast('Branch Staff, BC or BM submit financial records for their own branch.');return;}const f=S.financials.find(x=>x.member_id===id);openModal('Sync actual document records',`<form onsubmit="event.preventDefault();handleCmsAction(this,'sync','${id}')">${recordLogButton(id)}<div class="form-grid">${field('Active savings balance','savings',f?.savings??'','number')}<label>Paid-up share capital (optional)<input name="share_capital" type="number" min="0" step="0.01" value="${e(f?.share_capital??'')}" placeholder="Not yet verified"><span class="hint">Use the actual documented balance. Leave blank to retain the existing value.</span></label>${field('Outstanding loan balance','loan_balance',f?.loan_balance??'','number')}${field('Annual interest (%)','annual_interest',f?.annual_interest??'','number')}<label>Loan status<select name="loan_status">${['No active loan','Active','Paid','Overdue','Restructured'].map(v=>`<option ${f?.loan_status===v?'selected':''}>${v}</option>`).join('')}</select></label>${field('Record date','as_of',today(),'date')}<label>Record reference (optional)<input name="source_reference" maxlength="300" placeholder="Ledger number, statement date or form ID"><span class="hint">Leave blank to use the attached filenames.</span></label>${paymentScheduleEditor(f?.schedule||[])}${supportingDocumentsPicker()}<label class="full">Reason / Comments / Notes<textarea name="reason" minlength="3" maxlength="5000" required></textarea></label></div><p class="smalltext">${S.role==='BM'?'Your submission records BM screening and goes to the assigned DM for final approval.':'The assigned BM screens these documents, then the assigned DM approves and updates the member’s balances.'}</p><button type="submit" class="primary">${S.role==='BM'?'Submit BM-screened records to DM':'Submit for BM screening'}</button></form>`,{className:'financial-sync-dialog'});}
function canReview(q){
 if(!S.session||!requestMember(q)||!canReadBranch(q.branch_id))return false;
 const own=q.submitted_by===S.session.user.id;
 if(q.kind==='Profile edit')return !own&&q.status==='Pending'&&['BM','DM'].includes(S.role);
 if(q.kind==='Financial sync'&&q.status==='BM approved')return S.role==='DM'&&Boolean(q.bm_reviewer);
 if(own)return false;
 return q.kind==='Financial sync'&&q.status==='Pending'&&S.role==='BM'||q.kind==='Membership approval'&&q.status==='BM approved'&&S.role==='DM'&&Boolean(q.bm_reviewer)&&q.bm_reviewer!==S.session.user.id;
}
function approvalsView(){return requestsView('Profile edit','Member edit approvals','Branch Staff wait for BM or DM approval before editing. Approved permission can be used once.');}
function financialRequestStatus(q){return ({Pending:'Awaiting BM screening','BM approved':'Awaiting DM approval','DM approved':'BM screening required',Applied:q.kind==='Membership approval'?'Membership approved':'Synchronized',Rejected:'Rejected',Cancelled:'Cancelled'})[q.status]||q.status;}
function financialReviewHint(q){
 if(q.status==='Applied')return q.kind==='Membership approval'?'Membership approved and activated. This final record is read-only.':'Synchronization complete. This final record is read-only.';
 if(['Rejected','Cancelled'].includes(q.status))return 'This request is closed. A new submission is required for further updates.';
 if(q.status==='Pending')return canReview(q)?'Review the original documents, then send your screening decision to the assigned DM.':'Awaiting screening by this branch’s Branch Manager.';
 if(canReview(q)){
  if(q.kind==='Financial sync'&&q.bm_reviewer===S.session.user.id)return 'Your BM screening remains recorded. As the currently assigned District Manager, you can give final approval and synchronize these records.';
  return 'Final DM approval: review the BM-screened records, then approve and publish the verified result to the member’s profile.';
 }
 if(S.role==='DM'&&canReadBranch(q.branch_id)){
  if(!q.bm_reviewer)return 'A recorded BM screening is required before final DM approval.';
  if(q.kind==='Membership approval'&&(q.submitted_by===S.session.user.id||q.bm_reviewer===S.session.user.id))return 'Membership approval requires screening by a separate Branch Manager before your DM review.';
 }
 return 'Awaiting final approval by this branch’s assigned District Manager. Sign in with the assigned DM account to approve.';
}

function financialView(){return heading('Financial synchronization','Actual savings and loan records · BM screening followed by final approval from the assigned DM.')+`<section class="card finance-panel"><div class="card-head"><h2>Synchronization requests</h2></div>${requestList(currentMemberRequests().filter(q=>q.kind==='Financial sync'),'Financial synchronization requests')}</section><section class="card finance-panel"><div class="card-head"><h2>Member financial records</h2></div><div class="finance-filters"><label>Search member<input type="search" placeholder="Name or exact account number" value="${e(S.financeSearch)}" oninput="S.financeSearch=this.value;S.financePage=1;refreshFinancialRecords()"></label><label>Records<select onchange="S.financeStatus=this.value;S.financePage=1;refreshFinancialRecords()">${memberFilterOptions([['all','All members'],['missing','No financial records'],['pending','Awaiting verification'],['recorded','Recorded balances']],S.financeStatus)}</select></label></div><div id="financialRecordList">${financialRecordList()}</div></section>`;}
function financialRecordRows(){const branches=new Set(allowedBranches().map(b=>b.id));return scoped(S.profiles).filter(p=>!p.archived_at&&p.onboarding_complete!==false&&p.registration_kind!=='Staff'&&!directoryAssignment(p)&&branches.has(p.branch_id)).filter(p=>{const record=S.financials.find(f=>f.member_id===p.id),pending=S.requests.some(q=>q.member_id===p.id&&q.kind==='Financial sync'&&['Pending','BM approved'].includes(q.status));return (S.financeStatus==='all'||S.financeStatus==='missing'&&!record||S.financeStatus==='recorded'&&record||S.financeStatus==='pending'&&pending)&&memberMatches(p,S.financeSearch);}).sort((a,b)=>a.full_name.localeCompare(b.full_name));}
function financialRecordList(){const rows=financialRecordRows(),size=20,pages=Math.max(1,Math.ceil(rows.length/size));S.financePage=Math.min(pages,Math.max(1,S.financePage));const start=(S.financePage-1)*size;return `<ul class="finance-record-list">${rows.slice(start,start+size).map(p=>{const f=S.financials.find(f=>f.member_id===p.id),pending=S.requests.find(q=>q.member_id===p.id&&q.kind==='Financial sync'&&['Pending','BM approved'].includes(q.status));return `<li class="finance-record"><div class="finance-record-heading"><div><h3>${e(p.full_name)}</h3><p>${e(p.account_number||'ID not assigned')} · ${e(bn(p.branch_id))}</p></div>${statusPill(pending?financialRequestStatus(pending):f?'Synchronized':'Records required')}</div>${!f?'<p class="finance-record-notice">No financial records yet. Update and verification required.</p>':''}<dl class="finance-record-values">${detail('Savings',f?money(f.savings):'Not recorded')}${detail('Share capital',f?e(shareCapitalValue(f)):'Not recorded')}${detail('Loan balance',f?money(f.loan_balance):'Not recorded')}${detail('Loan status',f?e(f.loan_status):'Not recorded')}</dl><div class="finance-record-footer"><span>${f?'Verified record as of '+e(f.as_of):p.membership_status==='Active'&&p.account_number?'Submit the actual balances with original supporting documents.':'Membership approval and an official ID are required before a balance submission.'}</span><div class="flex">${f?button('View record',`financialRecordDialog('${p.id}')`,'outline small','eye'):''}${p.membership_status==='Active'&&p.account_number&&canSubmitBalances()?button('Update records',`syncDialog('${p.id}')`,'outline small','edit'):button('View member',`memberDialog('${p.id}')`,'outline small','user')}</div></div></li>`;}).join('')}</ul>${rows.length?'':empty('No matching member records','Choose another branch or change the record filter.')}<nav class="pagination"><span>${rows.length?start+1:0}–${Math.min(start+size,rows.length)} of ${rows.length} members · 20 per page</span><div class="flex"><button type="button" class="outline small" onclick="S.financePage--;refreshFinancialRecords()" ${S.financePage===1?'disabled':''}>Previous</button><span>Page ${S.financePage} of ${pages}</span><button type="button" class="outline small" onclick="S.financePage++;refreshFinancialRecords()" ${S.financePage===pages?'disabled':''}>Next</button></div></nav>`;}
function refreshFinancialRecords(){$('financialRecordList').innerHTML=financialRecordList();}
function financialDetails(values){return `<dl class="details-list">${[['savings','Savings balance'],['share_capital','Share capital'],['loan_balance','Loan balance'],['loan_status','Loan status'],['annual_interest','Annual interest'],['as_of','Record date']].map(([key,label])=>detail(label,auditFormattedValue(key,values[key]))).join('')}</dl>${values.source_reference?`<p class="financial-reference"><b>Document reference</b><span>${e(values.source_reference)}</span></p>`:''}${values.schedule?.length?scheduleView(values.schedule):'<p class="hint">No payment schedule supplied.</p>'}`;}
function financialRecordDialog(id){const p=S.profiles.find(p=>p.id===id),f=S.financials.find(f=>f.member_id===id);if(!p||!f||!canReadProfile(p))return;openModal('Verified financial record',`<p class="smalltext">${e(p.full_name)} · ${e(p.account_number)} · ${e(bn(p.branch_id))}</p><p class="financial-stage">${statusPill('Synchronized')}<span>This finalized record is read-only.</span></p>${financialDetails(f)}<h3>Original supporting documents</h3><ul class="document-list">${requestDocuments(f).map((file,i)=>`<li>${button(e(file.name),`viewFinancialDocument('${id}',${i})`,'outline small','file')}<small>${(Number(file.size||0)/1024/1024).toFixed(2)} MB</small></li>`).join('')}</ul>${button('Cashier receipts',`memberPaymentsDialog('${id}')`,'outline','file')}`,{className:'financial-review-dialog'});}
async function viewFinancialDocument(id,index){const f=S.financials.find(f=>f.member_id===id);if(!f)return;const file=requestDocuments(f)[index];if(!file)return;try{const url=await signedUrl('occci-documents',file.path),a=document.createElement('a');a.href=url+(url.includes('?')?'&':'?')+'download='+encodeURIComponent(file.name);a.download=file.name;a.target='_blank';a.rel='noopener noreferrer';a.click();}catch(err){$('actionMessage').textContent=err.message;}}
function requestList(rows,title){return `<ul class="request-list" aria-label="${e(title)}">${rows.map(q=>`<li class="request-list-row"><div class="request-list-info"><div class="request-list-title"><h2>${e(S.profiles.find(p=>p.id===q.member_id)?.full_name||'Member')}</h2>${statusPill(['Financial sync','Membership approval'].includes(q.kind)?financialRequestStatus(q):q.status)}</div><p class="request-list-meta">${e(bn(q.branch_id))} · ${e(q.created_at.slice(0,10))}${q.note?` <span class="request-list-note">· ${e(q.note)}</span>`:''}</p></div>${button(q.kind==='Financial sync'?(canReview(q)?q.status==='BM approved'?'Final approval':'Screen balances':'View details'):'View request',`requestDialog('${q.id}')`,'outline request-list-action','file')}</li>`).join('')}</ul>${rows.length?'':empty('No requests yet','Submitted requests for your assigned branches appear here.')}`;}
function requestsView(kind,title,subtitle){return heading(title,subtitle)+requestList(currentMemberRequests().filter(q=>q.kind===kind),title);}
function requestDialog(id){const q=S.requests.find(q=>q.id===id);if(!q||!canReadBranch(q.branch_id))return;if(!requestMember(q)){closeModal();toast('This member account is archived or no longer available in your workspace.');return;}const v=q.proposed,financial=q.kind==='Financial sync',membership=q.kind==='Membership approval',staged=financial||membership;openModal(financial?'Review actual balances':membership?'Review membership':q.kind,`${staged?`<p class="smalltext">${e(S.profiles.find(p=>p.id===q.member_id)?.full_name||'Member')} · ${e(bn(q.branch_id))}</p><div class="financial-stage">${statusPill(financialRequestStatus(q))}<span>${e(financialReviewHint(q))}</span></div>`:''}<p class="activity-note">${e(q.note)}</p>${financial?financialDetails(v):membership?`<dl class="details-list">${detail('Official ID / account number',e(v.account_number))}</dl>`:`<dl class="details-list">${Object.entries(v).filter(([k])=>k!=='schedule'&&k!=='permission_only').map(([k,val])=>detail(e(k.replaceAll('_',' ')),e(val))).join('')}</dl>`}${documentList(q,id)}<p class="smalltext">${e(staged?financialRequestStatus(q):q.status)}${q.review_note?' · '+e(q.review_note):''}</p>${canReview(q)?`${staged&&S.role==='DM'?'<h3 class="final-approval-title">Final DM approval</h3>':''}<form onsubmit="event.preventDefault();handleCmsAction(this,'review','${id}')"><label>Decision<select name="decision" onchange="requestReviewDecisionChanged(this.form,'${id}')"><option>Approve</option><option>Reject</option></select></label><label>Reason / Comments / Notes<textarea name="reason" minlength="3" maxlength="5000" required></textarea></label><button class="primary" type="submit">${reviewButtonLabel(q)}</button></form>`:staged&&S.role==='DM'&&q.status==='BM approved'?`<div class="financial-final-approval"><h3 class="final-approval-title">Final DM approval</h3><button type="button" class="primary" disabled aria-describedby="dmApprovalBlocked">${reviewButtonLabel(q)}</button><p id="dmApprovalBlocked" class="hint">${e(financialReviewHint(q))}</p></div>`:''}${q.kind==='Profile edit'&&q.status==='BM approved'&&q.submitted_by===S.session.user.id&&q.proposed.permission_only?button('Edit with approved permission',`editDialog('${q.member_id}','${id}')`,'primary','edit'):q.kind==='Profile edit'&&q.status==='BM approved'&&q.submitted_by===S.session.user.id?`<form onsubmit="event.preventDefault();handleCmsAction(this,'apply','${id}')"><button class="primary" type="submit">Apply approved changes</button></form>`:''}`,{className:staged?'financial-review-dialog':''});}
function reviewButtonLabel(q){return q.kind==='Membership approval'?'Approve and activate membership':q.kind==='Financial sync'?(q.status==='Pending'?'Save BM screening and send to DM':'Approve and synchronize'):'Record decision';}
function requestReviewDecisionChanged(form,id){const q=S.requests.find(q=>q.id===id);form.querySelector('[type=submit]').textContent=form.elements.decision.value==='Reject'?'Reject request':reviewButtonLabel(q);}
function requestDocuments(q){return q.evidence_files?.length?q.evidence_files:q.evidence_path?[{path:q.evidence_path,name:'Original source document'}]:[];}
function documentList(q,id){return requestDocuments(q).length?`<h3>Original supporting documents</h3><ul class="document-list">${requestDocuments(q).map((d,i)=>`<li>${button(d.name,`viewDocument('${id}',${i})`,'outline','file')}${d.size?`<small>${(d.size/1024/1024).toFixed(2)} MB</small>`:''}</li>`).join('')}</ul>`:'';}
function validateDocuments(files){if(!files.length||files.length>10)throw Error('Select 1 to 10 original supporting documents.');if(files.some(f=>!f.size||f.size>10*1024*1024))throw Error('Each document must contain data and be no larger than 10 MB.');if(files.reduce((n,f)=>n+f.size,0)>50*1024*1024)throw Error('The selected documents exceed 50 MB in total.');}
function supportingDocumentsPicker(){return `<section class="full document-picker" aria-labelledby="documentPickerTitle"><div class="document-picker-head"><h3 id="documentPickerTitle">Original supporting documents</h3><span id="documentCount" aria-live="polite">0 / 10 files</span></div><input class="sr-only" id="documentInput" type="file" name="evidence" multiple tabindex="-1" onchange="showSelectedDocuments(this)"><button type="button" class="outline document-add" onclick="this.form.elements.evidence.click()">${icon('plus')} Add files</button><p class="hint">PDF, Word, Excel, images or other documents. Add files in several selections. Maximum 10 files, 10 MB each, 50 MB total. Files stay private.</p><p id="documentError" class="document-error" role="alert" hidden></p><ul id="selectedDocuments" class="document-list selected-document-list" aria-label="Selected supporting documents"></ul></section>`;}
function selectedDocuments(form){return form._supportingDocuments||[];}
function renderSelectedDocuments(form){const files=selectedDocuments(form),busy=form.dataset.uploading==='true';form.querySelector('#selectedDocuments').innerHTML=files.map((f,index)=>`<li><span class="selected-document-info"><strong>${e(f.name)}</strong><small>${(f.size/1024/1024).toFixed(2)} MB</small></span><button type="button" class="document-remove" aria-label="Remove ${e(f.name)}" onclick="removeSelectedDocument(this.form,${index})" ${busy?'disabled':''}><span aria-hidden="true">×</span></button></li>`).join('');form.querySelector('#documentCount').textContent=`${files.length} / 10 files`;form.querySelector('.document-add').disabled=busy||files.length>=10;}
function documentSelectionError(form,message=''){const error=form.querySelector('#documentError');error.textContent=message;error.hidden=!message;}
function showSelectedDocuments(input){const form=input.form;if(form.dataset.uploading==='true')return;const added=Array.from(input.files||[]);input.value='';if(!added.length)return;const next=[...selectedDocuments(form),...added];try{validateDocuments(next);form._supportingDocuments=next;documentSelectionError(form);}catch(err){documentSelectionError(form,err.message);}renderSelectedDocuments(form);}
function removeSelectedDocument(form,index){if(form.dataset.uploading==='true')return;form._supportingDocuments=selectedDocuments(form).filter((file,i)=>i!==index);documentSelectionError(form);renderSelectedDocuments(form);form.querySelector('.document-add').focus();}
async function viewDocument(id,index=0){const q=S.requests.find(q=>q.id===id),file=requestDocuments(q)[index];try{const url=await signedUrl('occci-documents',file.path);const a=document.createElement('a');a.href=url+(url.includes('?')?'&':'?')+'download='+encodeURIComponent(file.name);a.download=file.name;a.target='_blank';a.rel='noopener noreferrer';a.click();}catch(err){$('actionMessage').textContent=err.message;}}
function editPermissionDialog(id){const pending=S.requests.find(q=>q.member_id===id&&q.kind==='Profile edit'&&q.submitted_by===S.session.user.id&&q.base_revision===S.profiles.find(p=>p.id===id)?.revision&&['Pending','BM approved'].includes(q.status));if(pending)return requestDialog(pending.id);openModal('Request permission to edit',`<p>You can edit this member’s profile after a BM or DM approves your request. No profile information changes at this step.</p><form onsubmit="event.preventDefault();handleCmsAction(this,'editPermission','${id}')"><label>Reason / Comments / Notes<textarea name="reason" minlength="3" required placeholder="Explain which information needs correction and why"></textarea></label><button type="submit" class="primary">Request BM / DM approval</button></form>`);}
function accountDialog(id){const p=S.profiles.find(p=>p.id===id);openModal('Assign / update ID number',`<form onsubmit="event.preventDefault();handleCmsAction(this,'account','${id}')"><label>Official ID / account number<input name="account" maxlength="40" value="${e(p.account_number||'')}" required></label><label>Reason / Comments / Notes<textarea name="reason" minlength="3" required></textarea></label><p class="hint">Use the official number verified by your branch. This records the ID without changing membership status.</p><button type="submit" class="primary">Save ID number</button></form>`);}
const auditFieldLabels={role:'Role',assigned_role:'Assigned position',employee_id:'Employee Number / ID',expires_at:'Invitation expires',revoked_at:'Revoked on',requested_role:'Requested position',membership_status:'Membership status',account_number:'Account number',full_name:'Complete name',first_name:'First name',last_name:'Last name',middle_name:'Middle name',contact_number:'Contact number',address:'Address',branch_id:'Branch',district:'District',savings:'Savings balance',share_capital:'Share capital',receipt_number:'Receipt number',payment_date:'Payment date',principal_amount:'Principal paid',interest_amount:'Interest paid',fees_amount:'Fees paid',savings_amount:'Savings deposit',share_capital_amount:'Share capital contribution',total_amount:'Total received',paid_amount:'Paid amount',loan_balance:'Loan balance',loan_status:'Loan status',annual_interest:'Annual interest',as_of:'Record date',source_reference:'Document reference',schedule:'Payment schedule',avatar:'Temporary avatar',photo_path:'Profile photo',evidence_path:'Source document',status:'Status',kind:'Type',title:'Title',body:'Content',published:'Publication',event_date:'Event date',decision:'Decision',active:'Branch status',archived_at:'Archived on',registration_kind:'Signup type',name:'Name',reason:'Reason / Comments / Notes'};
const auditInternalFields=new Set(['payment_id','id','member_id','user_id','actor','request_id','revision','base_revision','created_at','updated_at','created_by','submitted_by','reviewed_at','reviewed_by','bm_reviewer','dm_reviewer','admin_reviewer']);
function auditFields(data,prefix=''){if(!data||typeof data!=='object'||Array.isArray(data))return [];return Object.entries(data).flatMap(([key,value])=>{if(auditInternalFields.has(key))return [];const path=prefix?prefix+'.'+key:key;if(value&&typeof value==='object'&&!Array.isArray(value))return auditFields(value,path);return [{path,key,label:path.split('.').map(k=>auditFieldLabels[k]||(k==='proposed'?'Proposed details':k.replaceAll('_',' ').replace(/^./,c=>c.toUpperCase()))).join(' · '),value}];});}
function auditFormattedValue(key,value){if(value===null||value===undefined||value==='')return '<span class="audit-unset">Not set</span>';if(['savings','share_capital','loan_balance','amount','principal_amount','interest_amount','fees_amount','savings_amount','share_capital_amount','total_amount','paid_amount'].includes(key)&&Number.isFinite(Number(value)))return e(money(Number(value)));if(key==='annual_interest')return e(value)+'%';if(key==='branch_id')return e(S.branches.find(b=>b.id===value)?.name||'Branch no longer in directory');if(key==='district')return 'District '+e(value);if(['role','requested_role','assigned_role'].includes(key))return e(({Admin:'Admin',DM:'District Manager (DM)',BM:'Branch Manager (BM)',Staff:'Branch Staff (BS)',BC:'Branch Cashier (BC)',Member:'Member'})[value]||value);if(key==='photo_path')return 'Photo on file';if(key==='evidence_path')return 'Source document on file';if(typeof value==='boolean')return key==='published'?(value?'Published':'Draft'):key==='active'?(value?'Active':'Inactive'):(value?'Yes':'No');if(key==='avatar')return e(defaultAvatars.find(([id])=>id===value)?.[1]||value);if(Array.isArray(value)){if(!value.length)return '<span class="audit-unset">No entries</span>';if(key==='schedule')return `<ul class="audit-schedule">${value.map(item=>`<li>${e(item.date||'Date not recorded')} · ${e(Number.isFinite(Number(item.amount))?money(Number(item.amount)):'Amount not recorded')}${item.status?' · '+e(item.status):''}${Number(item.paid_amount)>0?' · Paid '+e(money(item.paid_amount)):''}</li>`).join('')}</ul>`;return `<ul class="audit-schedule">${value.map(item=>`<li>${item&&typeof item==='object'?auditFields(item).map(f=>e(f.label)+': '+auditFormattedValue(f.key,f.value)).join(' · '):e(item)}</li>`).join('')}</ul>`;}return e(value);}
function auditChangeDetails(entry){const previous=auditFields(entry.before_data),recorded=auditFields(entry.after_data),before=new Map(previous.map(f=>[f.path,f])),after=new Map(recorded.map(f=>[f.path,f]));const fields=recorded.length?recorded:previous;const changed=fields.filter(f=>!before.has(f.path)||!after.has(f.path)||JSON.stringify(before.get(f.path).value)!==JSON.stringify(after.get(f.path).value));if(!changed.length)return '<p class="hint">No additional field changes were recorded. See the action and reason above.</p>';return `<div class="audit-change-list">${changed.map(f=>`<section class="audit-change-row"><h4>${e(f.label)}</h4><div class="audit-change-values"><div><span class="audit-value-label">Previous</span><div>${before.has(f.path)?auditFormattedValue(f.key,before.get(f.path).value):'<span class="audit-unset">Not previously recorded</span>'}</div></div><div><span class="audit-value-label">Recorded</span><div>${after.has(f.path)?auditFormattedValue(f.key,after.get(f.path).value):'<span class="audit-unset">Not recorded in this action</span>'}</div></div></div></section>`).join('')}</div>`;}
function auditIdentityText(value){return typeof value==='string'?value.trim():'';}
function positionCode(role){return ({Admin:'Admin',DM:'DM',BM:'BM',Staff:'BS',BC:'BC',Member:'Member'})[role]||role;}
function auditSubject(entry){if(!entry.member_id&&!auditIdentityText(entry.subject_name))return null;const profile=S.profiles.find(p=>p.id===entry.member_id),name=auditIdentityText(entry.subject_name)||auditIdentityText(entry.after_data?.full_name)||auditIdentityText(entry.before_data?.full_name)||auditIdentityText(profile?.full_name)||'Name not recorded';const employeeId=auditIdentityText(entry.subject_name)?auditIdentityText(entry.subject_employee_id):auditIdentityText(entry.after_data?.employee_id)||auditIdentityText(entry.before_data?.employee_id)||auditIdentityText(profile?.employee_id),role=auditIdentityText(entry.subject_role)||auditIdentityText(entry.after_data?.role)||directoryAssignment(profile||{})?.role||'';return {name,employeeId,role};}
function auditSubjectSummary(entry){const subject=auditSubject(entry);return subject?`<span class="activity-subject">${e(subject.name)}${subject.role?' · '+e(positionCode(subject.role)):''}</span>`:'';}
function auditSubjectDetails(entry){const subject=auditSubject(entry);return subject?`<div class="activity-subject-detail"><span>Affected user</span><strong>${e(subject.name)}${subject.role?' · '+e(positionCode(subject.role)):''}</strong>${subject.employeeId?`<small>Employee ID: ${e(subject.employeeId)}</small>`:''}</div>`:'';}
function auditRows(rows,key='activity'){if(!rows.length)return empty('No activity yet','Actions and approval decisions are recorded here.');const size=20,pages=Math.ceil(rows.length/size),page=Math.min(pages,Math.max(1,S.activityPages[key]||1));S.activityPages[key]=page;const start=(page-1)*size,show=rows.slice(start,start+size);return rows.length?`<ul class="activity-list">${show.map(a=>`<li class="activity-list-item"><details class="activity-item"><summary class="activity-summary"><span class="activity-symbol">${icon('clock')}</span><span class="activity-label"><strong>${e(a.action)}</strong>${auditSubjectSummary(a)}<time datetime="${e(a.created_at)}">${e(new Date(a.created_at).toLocaleString())}</time></span><span class="activity-chevron">${icon('down')}</span></summary><div class="activity-body"><p class="activity-actor">${e(a.actor_name||S.profiles.find(p=>p.id===a.actor)?.full_name||(a.actor?'Cooperative user':'System'))}${a.actor_role?' · '+e(roleLabel(a.actor_role)):''}</p>${auditSubjectDetails(a)}<h4>Reason / Comments / Notes</h4><p class="activity-note">${e(a.note||'No notes recorded.')}</p><h4>Recorded changes</h4>${auditChangeDetails(a)}</div></details></li>`).join('')}</ul><nav class="activity-pager pagination" aria-label="Activity pages"><span>${start+1}–${Math.min(start+size,rows.length)} of ${rows.length} activities · 20 per page</span><div class="flex"><button type="button" class="outline small" aria-label="Previous activity page" onclick="changeActivityPage('${e(key)}',${page-1})" ${page===1?'disabled':''}>Previous</button><span class="activity-page-number">Page ${page} of ${pages}</span><button type="button" class="outline small" aria-label="Next activity page" onclick="changeActivityPage('${e(key)}',${page+1})" ${page===pages?'disabled':''}>Next</button></div></nav>`:empty('No activity yet','Actions and approval decisions are recorded here.');}

function changeActivityPage(key,page){S.activityPages[key]=page;if(key.startsWith('member:')){memberDialog(key.slice(7));const toggle=$('memberActivityToggle');if(toggle)toggleMemberActivity(toggle);}else if(key.startsWith('record:'))memberActivityDialog(key.slice(7));else if(key.startsWith('report:'))reportHistoryDialog(key.slice(7));else if(key.startsWith('work:'))workHistoryDialog(key.slice(5));else render();const root=/^(member|record|report|work):/.test(key)?$('modalContent'):$('main'),row=root.querySelector?.('.activity-summary');row?.scrollIntoView?.({block:'nearest'});row?.focus?.({preventScroll:true});}

function cmsAuditRows(rows){return scoped(rows).filter(a=>S.auditRole==='all'||a.actor_role===S.auditRole).sort((a,b)=>S.auditSort==='oldest'?Date.parse(a.created_at)-Date.parse(b.created_at)||Number(a.id)-Number(b.id):Date.parse(b.created_at)-Date.parse(a.created_at)||Number(b.id)-Number(a.id));}
function auditView(rows){if(!isStaff())return heading('Activity log',`Recorded changes and approvals. ${rows.length} entries.`)+`<section class="card">${auditRows(rows)}</section>`;const visible=cmsAuditRows(rows);return heading('CMS activity log','Recorded actions within your assigned district or branch.')+`<section class="card cms-activity-panel"><div class="activity-toolbar"><nav class="activity-role-tabs" aria-label="Activity by position">${[['all','All'],['Admin','Admin'],['DM','DM'],['BM','BM'],['Staff','BS'],['BC','BC']].map(([role,label])=>`<button type="button" onclick="S.auditRole='${role}';S.activityPages.activity=1;render()" aria-pressed="${S.auditRole===role}">${label}</button>`).join('')}</nav><label>Sort<select onchange="S.auditSort=this.value;S.activityPages.activity=1;render()"><option value="newest" ${S.auditSort==='newest'?'selected':''}>Newest first</option><option value="oldest" ${S.auditSort==='oldest'?'selected':''}>Oldest first</option></select></label></div><p class="smalltext">${visible.length} accessible entries · ${S.auditRole==='all'?'All positions':roleLabel(S.auditRole)} · 20 per page</p>${auditRows(visible)}</section>`;}
function contentView(cms,withHeading=true){const rows=S.content.filter(c=>(cms||c.published)&&(cms||S.scope==='all'||c.branch_id===S.scope||!c.branch_id));return (withHeading?heading(cms?'Content management':'Cooperative updates',cms?'Manage announcements, events and services in your assigned scope.':'Updates from your cooperative.',cms&&['Admin','DM','BM'].includes(S.role)?button('Add content',"contentDialog('')",'primary','plus'):''):'<h2>Cooperative updates</h2>')+`<div class="request-grid">${rows.map(c=>`<article class="card"><span class="pill blue">${e(c.kind)}${c.published?'':' · Draft'}</span><h2 class="spacer">${e(c.title)}</h2><p class="content-body">${e(c.body)}</p>${c.event_date?`<p>${e(c.event_date)}</p>`:''}${cms&&['Admin','DM','BM'].includes(S.role)?button('Edit',`contentDialog('${c.id}')`,'outline','edit')+button('Delete',`removeDialog('Content','${c.id}')`,'danger'):''}</article>`).join('')||empty('No content published','The CMS will supply announcements, events and services.')}</div>`;}
function contentDialog(id){const c=S.content.find(c=>c.id===id)||{};openModal(id?'Edit content':'Create content',`<form onsubmit="event.preventDefault();handleCmsAction(this,'content','${id}')"><div class="form-grid"><label>Type<select name="kind">${['Announcement','Event','Service'].map(k=>`<option ${c.kind===k?'selected':''}>${k}</option>`).join('')}</select></label><label>Branch scope<select name="branch_id">${['Admin','DM'].includes(S.role)?'<option value="">'+(S.role==='Admin'?'All branches':'My district')+'</option>':''}${branchOptions(c.branch_id,false,true)}</select></label>${field('Title','title',c.title||'')}${field('Event date (optional)','event_date',c.event_date||'','date',false)}<label class="full">Content<textarea name="body" required>${e(c.body||'')}</textarea></label><label>Publication<select name="published"><option value="true" ${c.published!==false?'selected':''}>Published</option><option value="false" ${c.published===false?'selected':''}>Draft</option></select></label><label class="full">Reason / Comments / Notes<textarea name="reason" minlength="3" required></textarea></label></div><button class="primary" type="submit">Save content</button></form>`);}
function branchesView(){const rows=S.role==='Admin'?S.branches:allowedBranches(),districts=[...new Set(rows.map(b=>b.district))].sort((a,b)=>a-b);if(!districts.includes(S.directoryDistrict))S.directoryDistrict=null;const selected=S.directoryDistrict;return heading(selected?'District '+selected+' branches':'Branch directory',selected?'Select a branch to view or manage its details.':'Select a district to view its branches.',(selected?button('All districts',"S.directoryDistrict=null;render()",'outline','location'):'')+(S.role==='Admin'?button('Add branch',"branchDialog('')",'primary','plus'):''))+`<div class="request-grid">${selected?rows.filter(b=>b.district===selected).map(b=>`<section class="card"><span class="iconbox">${icon('location')}</span><h2>OCCCI ${e(b.name)} Branch</h2><p>District ${b.district} · ${b.active?'Active':'Inactive'}</p>${S.role==='Admin'?button('Edit',`branchDialog('${e(b.id)}')`,'outline','edit')+button('Deactivate',`removeDialog('Branch','${e(b.id)}')`,'danger'):''}</section>`).join(''):districts.map(d=>`<section class="card district-card"><span class="iconbox">${icon('location')}</span><h2>District ${d}</h2><p>${rows.filter(b=>b.district===d).length} branches · ${rows.filter(b=>b.district===d&&b.active).length} active</p>${button('View branches',`S.directoryDistrict=${d};render()`,'primary','location')}</section>`).join('')||empty('No districts assigned','Your assigned branch directory will appear here.')}</div>`;}
function branchDialog(id){const b=S.branches.find(b=>b.id===id)||{};openModal('Branch details',`<form onsubmit="event.preventDefault();handleCmsAction(this,'branch','${e(id)}')"><div class="form-grid">${id?'':field('Internal branch reference','id')}${field('Branch name','name',b.name||'')}<label>District<select name="district">${[1,2,3,4,5,6].map(d=>`<option ${(b.district||S.directoryDistrict||1)===d?'selected':''}>${d}</option>`).join('')}</select></label><label class="full">Reason / Comments / Notes<textarea name="reason" minlength="3" required></textarea></label></div><button type="submit" class="primary">Save branch</button></form>`);}
function setTeamTab(tab){if(!['Directory','Applications','Hierarchy'].includes(tab)||tab==='Applications'&&S.role!=='Admin')return;S.page='Team';S.teamTab=tab;S.pageNumber=1;S.teamPage=1;render();}
function teamView(){const tabs=[['Directory','OCCCI Staff'],...(S.role==='Admin'?[['Applications','Staff Applications']]:[]),['Hierarchy','Cooperative Hierarchy']];if(!tabs.some(([tab])=>tab===S.teamTab))S.teamTab='Directory';const subtitles={Directory:'Approved cooperative personnel, grouped by district and branch.',Applications:'Review employee applications and assign their workplace.',Hierarchy:'Positions and assignments within your authorized locations.'};return heading('Team',subtitles[S.teamTab])+`<nav class="team-workspace-tabs" aria-label="Team sections">${tabs.map(([tab,label])=>`<button type="button" onclick="setTeamTab('${tab}')" aria-pressed="${S.teamTab===tab}">${label}${tab==='Applications'?`<span class="portal-count ${S.applications.some(a=>a.status==='Pending')?'has-pending':''}">${S.applications.filter(a=>a.status==='Pending').length}</span>`:''}</button>`).join('')}</nav>`+(S.teamTab==='Directory'?membersView(false):S.teamTab==='Applications'?staffApplicationsView(false):teamHierarchyView());}
function teamPositionTabs(){return [['Admin','Admin'],['DM','District Managers (DM)'],['BM','Branch Managers (BM)'],['Staff','Branch Staff (BS)'],['BC','Branch Cashiers (BC)']].filter(([role])=>role==='Admin'?S.role==='Admin':role==='DM'?['Admin','DM'].includes(S.role):isStaff());}
function teamHierarchyBranches(){return allowedBranches().filter(b=>S.scope==='all'||b.id===S.scope);}
function teamHierarchyFilters(){const tabs=teamPositionTabs();if(!tabs.some(([role])=>role===S.teamRoleTab))S.teamRoleTab=tabs[0]?.[0]||'Staff';const branches=teamHierarchyBranches(),districts=[...new Set(branches.map(b=>b.district))].sort((a,b)=>a-b);if(S.teamDistrict!=='all'&&!districts.includes(Number(S.teamDistrict)))S.teamDistrict='all';const options=branches.filter(b=>S.teamDistrict==='all'||b.district===Number(S.teamDistrict));if(S.teamBranch!=='all'&&!options.some(b=>b.id===S.teamBranch))S.teamBranch='all';return {tabs,districts,branches:options};}
function teamHierarchyRows(){teamHierarchyFilters();const role=S.teamRoleTab,q=S.teamSearch.trim().toLowerCase();return S.team.map(t=>({t,p:S.profiles.find(p=>p.id===t.user_id)})).filter(({t,p})=>{if(!p||p.archived_at||!canReadProfile(p)||t.role!==role)return false;if(t.role==='Admin')return S.role==='Admin'&&(!q||memberMatches(p,q)||(p.email||'').toLowerCase().includes(q));const district=t.role==='DM'?t.district:S.branches.find(b=>b.id===t.branch_id)?.district;if(t.role==='DM'){if(!['Admin','DM'].includes(S.role)||S.role==='DM'&&t.district!==S.assignment?.district)return false;}else if(!canReadBranch(t.branch_id))return false;if(S.scope!=='all'&&(t.role==='DM'?district!==S.branches.find(b=>b.id===S.scope)?.district:t.branch_id!==S.scope))return false;if(S.teamDistrict!=='all'&&district!==Number(S.teamDistrict))return false;if(!['Admin','DM'].includes(t.role)&&S.teamBranch!=='all'&&t.branch_id!==S.teamBranch)return false;return !q||memberMatches(p,q)||(p.email||'').toLowerCase().includes(q);}).sort((a,b)=>(a.t.district||S.branches.find(v=>v.id===a.t.branch_id)?.district||0)-(b.t.district||S.branches.find(v=>v.id===b.t.branch_id)?.district||0)||bn(a.t.branch_id).localeCompare(bn(b.t.branch_id))||a.p.full_name.localeCompare(b.p.full_name));}
function teamHierarchyDistrictChanged(value){S.teamDistrict=value;S.teamBranch='all';S.teamPage=1;render();}
function teamHierarchyRoleChanged(role){if(!teamPositionTabs().some(([r])=>r===role))return;S.teamRoleTab=role;S.teamPage=1;render();}
function teamHierarchyList(){const rows=teamHierarchyRows(),pages=Math.max(1,Math.ceil(rows.length/20));S.teamPage=Math.min(Math.max(1,S.teamPage),pages);const groups=new Map();for(const row of rows.slice((S.teamPage-1)*20,S.teamPage*20)){const {t}=row,d=t.role==='DM'?t.district:S.branches.find(b=>b.id===t.branch_id)?.district,key=t.role==='Admin'?'global':t.role==='DM'?'district:'+d:'branch:'+t.branch_id,title=t.role==='Admin'?'Head office · All districts':t.role==='DM'?'District '+d:'District '+d+' · OCCCI '+bn(t.branch_id)+' Branch';if(!groups.has(key))groups.set(key,{title,rows:[]});groups.get(key).rows.push(row);}return `<p class="directory-count">${rows.length} ${rows.length===1?'assignment':'assignments'} · 20 per page</p>${[...groups.values()].map(g=>`<section class="people-group"><div class="people-group-heading"><h3>${e(g.title)}</h3><span>${g.rows.length} displayed</span></div><ul class="people-list">${g.rows.map(({t,p})=>`<li class="team-person-row"><span class="avatar">${avatarArt(p.avatar||'lady')}</span><div class="directory-person-info"><h3>${e(p.full_name)}<span class="directory-name-position"> · ${e(STAFF_ROLE_LABELS[t.role])}</span></h3><p>${e(p.employee_id||'Employee ID not recorded')}</p><small class="directory-email">${e(p.email||'Email not recorded')}</small></div><div class="team-person-actions">${button('View',`memberDialog('${p.id}')`,'outline small','eye')}${S.role==='Admin'?button('Edit',`teamDialog('${p.id}')`,'outline small','edit')+button('Remove',`removeDialog('Team','${p.id}')`,'danger small','close'):''}</div></li>`).join('')}</ul></section>`).join('')||empty('No matching assignments','Choose another position, district or branch, or change the search.')}<nav class="pagination" aria-label="Team pages"><span>Page ${S.teamPage} of ${pages}</span><div class="flex"><button type="button" class="outline small" onclick="S.teamPage--;refreshTeamHierarchy()" ${S.teamPage===1?'disabled':''}>Previous</button><button type="button" class="outline small" onclick="S.teamPage++;refreshTeamHierarchy()" ${S.teamPage===pages?'disabled':''}>Next</button></div></nav>`;}
function refreshTeamHierarchy(){const list=$('teamHierarchyList');if(list)list.innerHTML=teamHierarchyList();}
function teamHierarchyView(){const {tabs,districts,branches}=teamHierarchyFilters(),districtEnabled=S.teamRoleTab!=='Admin',branchEnabled=['BM','Staff','BC'].includes(S.teamRoleTab);return `<section class="card team-hierarchy-panel"><div class="card-head"><div><h2>Cooperative hierarchy</h2><p class="smalltext">Admin · District Manager · Branch Manager · Branch Staff / Branch Cashier</p></div>${S.role==='Admin'?button('Assign role',"teamDialog('')",'primary small','plus'):''}</div><nav class="team-role-tabs" aria-label="Positions">${tabs.map(([role,label])=>`<button type="button" onclick="teamHierarchyRoleChanged('${role}')" aria-pressed="${S.teamRoleTab===role}">${label}</button>`).join('')}</nav><div class="team-hierarchy-filters"><label>Search staff<input type="search" value="${e(S.teamSearch)}" placeholder="Name, employee ID or email" oninput="S.teamSearch=this.value;S.teamPage=1;refreshTeamHierarchy()"></label><label>District<select aria-label="Hierarchy district" onchange="teamHierarchyDistrictChanged(this.value)" ${districtEnabled?'':'disabled'}>${memberFilterOptions([['all',districtEnabled?'All assigned districts':'All districts'],...districts.map(d=>[d,'District '+d])],districtEnabled?S.teamDistrict:'all')}</select></label><label>Branch<select aria-label="Hierarchy branch" onchange="S.teamBranch=this.value;S.teamPage=1;refreshTeamHierarchy()" ${branchEnabled?'':'disabled'}>${memberFilterOptions([['all',S.teamRoleTab==='Admin'?'All branches':S.teamRoleTab==='DM'?'All district branches':'All assigned branches'],...branches.map(b=>[b.id,b.name])],branchEnabled?S.teamBranch:'all')}</select></label></div><div id="teamHierarchyList">${teamHierarchyList()}</div></section>`;}
function staffApplicationsView(withHeading=true){if(S.role!=='Admin')return '';const rows=S.applications.filter(a=>a.status==='Pending'),pages=Math.max(1,Math.ceil(rows.length/20));S.staffApplicationPage=Math.min(Math.max(1,S.staffApplicationPage),pages);return (withHeading?heading('Staff applications',`${rows.length} awaiting review · Admin assigns the position and workplace.`,button('Generate invitation','staffInviteDialog()','outline small','plus')):`<div class="team-section-heading"><p class="smalltext">${rows.length} awaiting review</p>${button('Generate invitation','staffInviteDialog()','outline small','plus')}</div>`)+`<section class="card reports-panel"><ul class="request-list">${rows.slice((S.staffApplicationPage-1)*20,S.staffApplicationPage*20).map(a=>{const p=S.profiles.find(p=>p.id===a.user_id);return `<li class="request-list-row"><span class="applicant-avatar">${avatarArt(p?.avatar||'lady')}</span><div class="request-list-info"><div class="request-list-title"><h2>${e(p?.full_name||'Applicant')}</h2>${statusPill(a.status)}</div><p class="request-list-meta">Employee ID: ${e(p?.employee_id||'Needs verification')} · ${e(p?.email||'Email not recorded')} · ${e(p?.contact_number||'Contact not recorded')}</p></div>${button('Review application',`staffApplicationDialog('${a.user_id}')`,'outline small')}</li>`;}).join('')}</ul>${rows.length?'':empty('No pending staff applications','Invite an employee through Admin settings. Applications appear after the employee verifies the code and submits their details.')}<nav class="pagination"><span>Page ${S.staffApplicationPage} of ${pages} · 20 per page</span><div class="flex">${button('Previous','S.staffApplicationPage--;render()','outline small').replace('<button ','<button '+(S.staffApplicationPage===1?'disabled ':''))}${button('Next','S.staffApplicationPage++;render()','outline small').replace('<button ','<button '+(S.staffApplicationPage===pages?'disabled ':''))}</div></nav></section>`;}
function staffApplicationDialog(id){if(S.role!=='Admin')return;const a=S.applications.find(a=>a.user_id===id),p=S.profiles.find(p=>p.id===id);if(!a||!p)return;const draft=a.review_draft||{},role=STAFF_ROLES.includes(draft.role)?draft.role:'Staff',district=draft.district||S.branches.find(b=>b.id===draft.branch_id)?.district||S.branches.find(b=>b.active)?.district;openModal('Review OCCCI Staff application',`<div class="staff-applicant-head"><span class="avatar" id="staffApplicantAvatar" data-user="${e(id)}">${avatarArt(p.avatar||'lady')}</span><div><h2>${e(p.full_name)}</h2><p class="smalltext">${e(p.contact_number)} · ${e(p.email||'Email not recorded')} · ${a.invite_id?'Private invitation verified':'Existing application'}</p></div></div><form data-assignment-target="${e(id)}" onsubmit="event.preventDefault();handleCmsAction(this,event.submitter?.value==='pending'?'staffSave':'staffReview','${id}')"><label>Decision<select name="decision" onchange="staffReviewDecisionChanged()"><option ${draft.decision!=='Reject'?'selected':''}>Approve</option><option ${draft.decision==='Reject'?'selected':''}>Reject</option></select></label><div id="staffAssignmentFields"><label>Employee Number / ID<input name="employee_id" value="${e(draft.employee_id||p.employee_id||'')}" required minlength="2" maxlength="50"></label><label>Assign position<select id="teamRole" name="role" onchange="teamRoleChanged()">${STAFF_ROLES.map(r=>`<option value="${r}" ${r===role?'selected':''}>${STAFF_ROLE_LABELS[r]}</option>`).join('')}</select></label><p class="hint" id="teamScopeHint"></p><p class="hint manager-slot-hint" data-manager-slot role="status" hidden></p><div class="form-grid team-scope-fields"><label id="teamDistrictField">District<select id="teamDistrict" name="district" onchange="teamDistrictChanged()" required>${teamDistrictOptions(district)}</select></label><label id="teamBranchField">Branch<select id="teamBranch" name="branch_id" onchange="managerSlotChanged(this.form)" required>${teamBranchOptions(district,draft.branch_id||'')}</select></label></div></div><label>Reason / Comments / Notes<textarea name="reason" minlength="3" maxlength="5000" required rows="2">${e(draft.note||'')}</textarea></label><p class="hint">Save as Pending retains your review without granting access. Approval activates the assigned position. Branch Staff and BC work reports go to their BM.</p>${a.draft_saved_at?`<p class="smalltext">Pending review last saved ${e(new Date(a.draft_saved_at).toLocaleString())}.</p>`:''}${adminPositionPasswordField(true)}<div class="staff-review-actions"><button type="submit" value="final" class="primary">Save and Approve</button><button type="submit" value="pending" class="outline">Save as Pending</button></div></form>`,{className:'staff-review-dialog'});staffReviewDecisionChanged();staffApplicantPhoto(id);}
function teamDistrictOptions(selected){return [...new Set(S.branches.filter(b=>b.active).map(b=>b.district))].sort((a,b)=>a-b).map(d=>`<option value="${d}" ${Number(selected)===d?'selected':''}>District ${d}</option>`).join('');}
function teamBranchOptions(district,selected=''){const rows=S.branches.filter(b=>b.active&&b.district===Number(district));return `<option value="">${rows.length?'Select a branch':'No active branches in this district'}</option>`+rows.map(b=>`<option value="${e(b.id)}" ${b.id===selected?'selected':''}>OCCCI ${e(b.name)} Branch</option>`).join('');}
function managerAssignmentConflict(target,values){
 const role=values.role;
 if(role==='DM'&&values.district&&S.team.some(t=>t.role==='DM'&&Number(t.district)===Number(values.district)&&t.user_id!==target))return `District ${values.district} already has a DM. Update the existing assignment before assigning a replacement.`;
 if(role==='BM'&&values.branch_id&&S.team.some(t=>t.role==='BM'&&t.branch_id===values.branch_id&&t.user_id!==target))return 'This branch already has a BM. Update the existing assignment before assigning a replacement.';
 return '';
}
function managerSlotChanged(form){
 if(!form)return;
 const role=form.elements.role?.value,target=form.dataset.assignmentTarget||form.elements.user_id?.value;
 const conflict=form.elements.decision?.value==='Reject'?'':managerAssignmentConflict(target,{role,district:form.elements.district?.value,branch_id:form.elements.branch_id?.value});
 const hint=form.querySelector('[data-manager-slot]');
 if(hint){hint.hidden=!conflict;hint.textContent=conflict;}
 const final=form.querySelector('button[type="submit"]:not([value="pending"])');
 if(final)final.disabled=Boolean(conflict);
 if(conflict){const password=form.querySelector('[data-admin-password]');if(password)password.value='';}
}
function teamDistrictChanged(){const branch=$('teamBranch');branch.innerHTML=teamBranchOptions($('teamDistrict').value,branch.value);managerSlotChanged(branch.form);}
function teamRoleChanged(){const role=$('teamRole').value,hasDistrict=role!=='Admin',hasBranch=['BM','Staff','BC'].includes(role);$('teamDistrictField').hidden=!hasDistrict;$('teamDistrict').disabled=!hasDistrict;$('teamDistrict').required=hasDistrict;$('teamBranchField').hidden=!hasBranch;$('teamBranch').disabled=!hasBranch;$('teamBranch').required=hasBranch;if(hasBranch)teamDistrictChanged();$('teamScopeHint').textContent=role==='Admin'?'Admin covers every district and branch.':role==='DM'?'District Manager access covers all branches in the selected district.':'Access is limited to the selected branch in this district.';updateAdminPositionPassword();managerSlotChanged($('teamRole').form);}
function adminPositionPasswordField(pendingAllowed){return `<label id="adminPositionPasswordField" hidden>Confirm your Admin password<input id="adminPositionPassword" type="password" data-admin-password data-pending-allowed="${pendingAllowed}" autocomplete="current-password" maxlength="1024" disabled><small>Required for every staff assignment or removal.${pendingAllowed?' Save as Pending does not assign access.':''}</small></label>`;}
function updateAdminPositionPassword(){const input=$('adminPositionPassword');if(!input?.matches?.('[data-admin-password]'))return;const decision=input.form.elements.decision?.value,required=decision!=='Reject';$('adminPositionPasswordField').hidden=!required;input.disabled=!required;input.required=required&&input.dataset.pendingAllowed!=='true';if(!required)input.value='';}
async function positionConfirmedRpc(form,actionKind,name,args){const v=args.values_json||{},needsPassword=['Team','Team removal','Account archive'].includes(actionKind)||(actionKind==='Staff application'&&args.decision==='Approve');if(!needsPassword)return rpc(name,args);if(S.role!=='Admin')throw Error('Only Admin can change staff assignments or archive accounts.');const input=form.querySelector('[data-admin-password]'),password=input?.value||'',adminId=S.session?.user?.id,email=S.session?.user?.email;if(!password)throw Error('Re-enter your Admin password to confirm this change.');if(!email)throw Error('Sign in with your Admin email before confirming a position.');let fresh=null;try{if(['Team','Staff application'].includes(actionKind)){const conflict=managerAssignmentConflict(args.target||args.record_id,v);if(conflict)throw Error(conflict);}const confirmation=await rpc('occci_begin_position_confirmation',{action_kind:actionKind,target:args.target||args.record_id,values_json:v});try{fresh=await api('/auth/v1/token?grant_type=password',{method:'POST',auth:false,data:{email,password}});}catch(err){throw Error('Admin password confirmation failed. Check your password and try again.');}if(!fresh?.access_token||fresh.user?.id!==adminId)throw Error('Password confirmation must belong to the signed-in Admin.');input.value='';return await api('/rest/v1/rpc/'+name,{method:'POST',auth:false,headers:{Authorization:'Bearer '+fresh.access_token},data:{...args,values_json:{...v,position_confirmation:confirmation}}});}finally{if(input)input.value='';if(fresh?.access_token)try{await api('/auth/v1/logout?scope=local',{method:'POST',auth:false,headers:{Authorization:'Bearer '+fresh.access_token}});}catch{}}}
function teamAssignmentValues(values){const role=values.role;if(!['Admin','DM','BM','Staff','BC'].includes(role))throw Error('Choose a valid role.');if(role==='Admin')return{role,branch_id:null,district:null};const district=Number(values.district);if(!S.branches.some(b=>b.active&&b.district===district))throw Error('Choose a district with active branches.');if(role==='DM')return{role,branch_id:null,district};const branch=S.branches.find(b=>b.active&&b.id===values.branch_id&&b.district===district);if(!branch)throw Error('Choose a branch in the selected district.');return{role,branch_id:branch.id,district:null};}
function teamDialog(id){const t=S.team.find(t=>t.user_id===id)||{},role=t.role||'Staff',district=t.district||S.branches.find(b=>b.id===t.branch_id)?.district||S.branches.find(b=>b.active)?.district;const labels={Admin:'Admin',DM:'District Manager (DM)',BM:'Branch Manager (BM)',Staff:'Branch Staff (BS)',BC:'Branch Cashier (BC)'};openModal('Team assignment',`<form data-assignment-target="${e(id)}" onsubmit="event.preventDefault();handleCmsAction(this,'team','${id}')"><label>Registered user<select name="user_id" ${id?'disabled':'required'} onchange="managerSlotChanged(this.form)">${id?'':'<option value="">Select a registered user</option>'}${S.profiles.filter(p=>p.onboarding_complete!==false).map(p=>`<option value="${p.id}" ${p.id===id?'selected':''}>${e(p.full_name)} · ${e(p.account_number||p.id)}</option>`).join('')}</select></label>${id===S.session.user.id?'<p class="hint">You are editing your own access. Keep another Admin before changing your role.</p>':''}<label>Role<select id="teamRole" name="role" onchange="teamRoleChanged()">${['Admin','DM','BM','Staff','BC'].map(r=>`<option value="${r}" ${role===r?'selected':''}>${labels[r]}</option>`).join('')}</select></label><p class="hint" id="teamScopeHint"></p><p class="hint manager-slot-hint" data-manager-slot role="status" hidden></p><div class="form-grid team-scope-fields"><label id="teamDistrictField" ${role==='Admin'?'hidden':''}>District<select id="teamDistrict" name="district" onchange="teamDistrictChanged()" ${role==='Admin'?'disabled':'required'}>${teamDistrictOptions(district)}</select></label><label id="teamBranchField" ${['BM','Staff','BC'].includes(role)?'':'hidden'}>Branch<select id="teamBranch" name="branch_id" onchange="managerSlotChanged(this.form)" ${['BM','Staff','BC'].includes(role)?'required':'disabled'}>${teamBranchOptions(district,t.branch_id)}</select></label></div><label>Reason / Comments / Notes<textarea name="reason" minlength="3" required></textarea></label>${adminPositionPasswordField(false)}<button type="submit" class="primary">Save assignment</button></form>`);teamRoleChanged();}

function removeDialog(kind,id){const c=kind==='Content'?S.content.find(c=>c.id===id):null;openModal('Delete / archive '+kind,`<p>${kind==='Content'?'Content will be removed from publication.':kind==='Branch'?'This branch will be deactivated. Existing records stay attached to it.':kind==='Team'?'The user will return to member access.':'The member will be archived and removed from active lists.'} The action remains in the activity log.</p><form onsubmit="event.preventDefault();handleCmsAction(this,'remove','${id}','${kind}')"><label>Reason / Comments / Notes<textarea name="reason" minlength="3" required></textarea></label>${['Team','Member'].includes(kind)?adminPositionPasswordField(false):''}<button type="submit" class="danger">Confirm</button></form>`);if(['Team','Member'].includes(kind))updateAdminPositionPassword();}
function paymentScheduleEditor(rows){return `<section class="full payment-schedule-editor" aria-labelledby="paymentScheduleTitle"><div class="payment-schedule-head"><h3 id="paymentScheduleTitle">Payment schedule</h3><span id="paymentScheduleCount">${rows.length} payments</span></div><p class="hint">Choose due dates from the calendar, or generate installments and adjust individual payments.</p><div class="schedule-generator"><label>First due date<input type="date" data-schedule-start value="${e(today())}"></label><label>Repeat<select data-schedule-frequency><option value="monthly">Monthly</option><option value="weekly">Weekly</option><option value="fortnightly">Every 2 weeks</option><option value="quarterly">Quarterly</option></select></label><label>Payments<input type="number" data-schedule-count min="1" max="360" step="1" value="1"></label><label>Amount per payment<input type="number" data-schedule-amount min="0" step="0.01" placeholder="₱ amount"></label><button type="button" class="outline small" onclick="generatePaymentSchedule(this.form)">${icon('calendar')} Generate</button></div><p id="paymentScheduleError" class="form-error" role="alert" hidden></p><ul id="paymentScheduleRows" class="payment-schedule-list">${rows.map(row=>paymentScheduleRow(row)).join('')}</ul><button type="button" class="outline small" onclick="addPaymentScheduleRow(this.form)">${icon('plus')} Add payment date</button><p class="hint">Multiple dates are supported. Remove a payment with ×. An empty schedule is allowed when there are no installments.</p></section>`;}
function paymentScheduleRow(row={}){return `<li class="payment-schedule-row"><label>Due date<input type="date" data-payment-date required value="${e(row.date||'')}"></label><label>Amount<input type="number" data-payment-amount required min="0" step="0.01" value="${e(row.amount??'')}"></label><label>Status<select data-payment-status>${['Scheduled','Paid','Overdue','Rescheduled','Cancelled'].map(status=>`<option ${status===(row.status||'Scheduled')?'selected':''}>${status}</option>`).join('')}</select></label><label>Paid to date<input type="number" data-payment-paid min="0" step="0.01" value="${e(row.paid_amount??0)}"></label><button type="button" class="icon-btn schedule-remove" aria-label="Remove payment" onclick="removePaymentScheduleRow(this)">${icon('close')}</button></li>`;}
function scheduleDate(value){if(!/^\d{4}-\d{2}-\d{2}$/.test(value))throw Error('Choose a valid due date from the calendar.');const [y,m,d]=value.split('-').map(Number),date=new Date(Date.UTC(y,m-1,d));if(date.getUTCFullYear()!==y||date.getUTCMonth()!==m-1||date.getUTCDate()!==d)throw Error('Choose a valid due date from the calendar.');return date;}
function scheduleISO(date){return [date.getUTCFullYear(),String(date.getUTCMonth()+1).padStart(2,'0'),String(date.getUTCDate()).padStart(2,'0')].join('-');}
function recurringPaymentDates(start,count,frequency){const date=scheduleDate(start);if(!Number.isInteger(count)||count<1||count>360||!['weekly','fortnightly','monthly','quarterly'].includes(frequency))throw Error('Choose 1 to 360 payments and a valid repeat interval.');return Array.from({length:count},(_,i)=>{if(['weekly','fortnightly'].includes(frequency))return scheduleISO(new Date(date.getTime()+i*(frequency==='weekly'?7:14)*86400000));const month=date.getUTCMonth()+i*(frequency==='quarterly'?3:1),last=new Date(Date.UTC(date.getUTCFullYear(),month+1,0)).getUTCDate();return scheduleISO(new Date(Date.UTC(date.getUTCFullYear(),month,Math.min(date.getUTCDate(),last))));});}
function paymentScheduleError(form,message=''){const node=form.querySelector('#paymentScheduleError');node.textContent=message;node.hidden=!message;}
function updatePaymentScheduleCount(form){const count=form.querySelectorAll('.payment-schedule-row').length;form.querySelector('#paymentScheduleCount').textContent=count+' '+(count===1?'payment':'payments');}
function addPaymentScheduleRow(form,row={}){const list=form.querySelector('#paymentScheduleRows');if(list.children.length>=360){paymentScheduleError(form,'The schedule can contain up to 360 payments.');return;}list.insertAdjacentHTML('beforeend',paymentScheduleRow(row));paymentScheduleError(form);updatePaymentScheduleCount(form);}
function removePaymentScheduleRow(button){const form=button.form;button.closest('.payment-schedule-row').remove();paymentScheduleError(form);updatePaymentScheduleCount(form);}
function generatePaymentSchedule(form){try{const count=Number(form.querySelector('[data-schedule-count]').value),value=form.querySelector('[data-schedule-amount]').value,amount=Number(value),start=form.querySelector('[data-schedule-start]').value,frequency=form.querySelector('[data-schedule-frequency]').value;if(value===''||!Number.isFinite(amount)||amount<0)throw Error('Enter a valid amount per payment.');if(form.querySelectorAll('.payment-schedule-row').length+count>360)throw Error('The schedule can contain up to 360 payments.');const dates=recurringPaymentDates(start,count,frequency);form.querySelector('#paymentScheduleRows').insertAdjacentHTML('beforeend',dates.map(date=>paymentScheduleRow({date,amount,status:'Scheduled'})).join(''));paymentScheduleError(form);updatePaymentScheduleCount(form);}catch(err){paymentScheduleError(form,err.message);}}
function readPaymentSchedule(form){const rows=[...form.querySelectorAll('.payment-schedule-row')];if(rows.length>360)throw Error('The schedule can contain up to 360 payments.');return rows.map(row=>{const date=row.querySelector('[data-payment-date]').value,value=row.querySelector('[data-payment-amount]').value,amount=Number(value),status=row.querySelector('[data-payment-status]').value;scheduleDate(date);if(value===''||!Number.isFinite(amount)||amount<0||!['Scheduled','Paid','Overdue','Rescheduled','Cancelled'].includes(status))throw Error('Check the amount and status of each scheduled payment.');const paid=cashierMoney(row.querySelector('[data-payment-paid]')?.value||0);if(paid>amount)throw Error('Paid to date cannot exceed the installment amount.');return {date,amount,status,...(paid>0?{paid_amount:paid}:{})};}).sort((a,b)=>a.date.localeCompare(b.date));}

function parseSchedule(text){return text.trim()?text.trim().split('\n').filter(Boolean).map(line=>{const [date,amount,status='Scheduled']=line.split(',').map(x=>x.trim());if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||!amount||!Number.isFinite(Number(amount))||Number(amount)<0)throw Error('Check each schedule line: date, amount, status.');return{date,amount:Number(amount),status};}):[];}
async function handleCmsAction(form,kind,id,extra){const buttons=[...form.querySelectorAll('button[type=submit],button:not([type])')],btn=buttons[0],disabled=buttons.map(b=>b.disabled);const buttonLabel=btn?.textContent;if(form.dataset.saving==='true')return;form.dataset.saving='true';buttons.forEach(b=>b.disabled=true);const f=new FormData(form),v=Object.fromEntries(f),reason=String(v.reason||'');try{
 if(kind==='staffSave'){const values_json=v.decision==='Approve'?{...teamAssignmentValues(v),employee_id:String(v.employee_id||'').trim(),decision:v.decision}:{decision:v.decision};await rpc('occci_save_staff_review',{target:id,values_json,reason});}
 if(kind==='staffReview'){const values_json=v.decision==='Approve'?{...teamAssignmentValues(v),employee_id:String(v.employee_id||'').trim()}:{};await positionConfirmedRpc(form,'Staff application','occci_review_staff',{target:id,decision:v.decision,values_json,reason});}
 if(kind==='membership')await rpc('occci_approve_member',{target:id,account:v.account,reason});
 if(kind==='account')await rpc('occci_assign_account',{target:id,account:v.account,reason});
 if(kind==='editPermission')await rpc('occci_submit_change',{target:id,request_kind:'Profile edit',values_json:{permission_only:true},evidence:null,reason});
 if(kind==='edit'){delete v.reason;if(isOperationalStaff())await rpc('occci_apply_authorized_edit',{request_id:extra,values_json:v,reason});else if(['DM','BM','Admin'].includes(S.role))await rpc('occci_manage_record',{record_kind:'Member',record_id:id,values_json:v,remove_record:false,reason});else throw Error('Member editing requires authorized cooperative access.');}
 if(kind==='sync'){if(!canSubmitBalances())throw Error('Financial submissions require assigned branch personnel.');const member=S.profiles.find(p=>p.id===id);if(member?.membership_status!=='Active'||!member.account_number)throw Error('Approve membership and assign its official ID before submitting actual balances.');const files=selectedDocuments(form).slice();validateDocuments(files);form.dataset.uploading='true';renderSelectedDocuments(form);const schedule=readPaymentSchedule(form),documents=[];for(const file of files){if(btn)btn.textContent=`Uploading ${documents.length+1} of ${files.length}…`;documents.push({path:await upload('occci-documents',file),name:file.name,size:file.size,type:file.type||'application/octet-stream'});}await rpc('occci_submit_financial_documents',{target:id,values_json:{savings:Number(v.savings),...(String(v.share_capital||'').trim()!==''?{share_capital:cashierMoney(v.share_capital)}:{}),loan_balance:Number(v.loan_balance),loan_status:v.loan_status,annual_interest:Number(v.annual_interest),as_of:v.as_of,source_reference:v.source_reference.trim()||files.map(f=>f.name).join('; ').slice(0,300),schedule},documents,reason});}
 if(kind==='review')await rpc('occci_review_change',{request_id:id,decision:v.decision,reason});if(kind==='apply')await rpc('occci_apply_edit',{request_id:id});
 if(['content','branch','team','remove'].includes(kind)){let record_kind=kind==='remove'?extra:({content:'Content',branch:'Branch',team:'Team'})[kind],values_json=v;if(record_kind==='Content'){if(kind==='remove')values_json=S.content.find(c=>c.id===id);else values_json={...v,district:S.role==='DM'&&!v.branch_id?S.assignment.district:null,published:v.published==='true'};}if(record_kind==='Team'){values_json=kind==='remove'?{}:teamAssignmentValues(v);id=id||v.user_id;if(!id)throw Error('Select a registered user.');if(S.team.find(t=>t.user_id===id)?.role==='Admin'&&(kind==='remove'||values_json.role!=='Admin')&&!S.team.some(t=>t.role==='Admin'&&t.user_id!==id))throw Error('Keep at least one Admin. Assign another Admin before changing or removing this assignment.');}if(record_kind==='Branch')id=id||v.id;await positionConfirmedRpc(form,record_kind==='Team'&&kind==='remove'?'Team removal':record_kind==='Member'&&kind==='remove'?'Account archive':record_kind,'occci_manage_record',{record_kind,record_id:id,values_json:values_json||{},remove_record:kind==='remove',reason});await loadBranches();}
 closeModal();await reload();if(!isStaff())S.page='Home';else if(!['Staff Applications','New Members'].includes(S.page)&&!currentNav().some(([page])=>page===S.page))S.page='Overview';render();toast(S.error?'Saved, but refreshing failed. Use Retry to reload.':kind==='staffSave'?'Review saved. The application remains pending without CMS access.':kind==='membership'?'BM screening saved. The member now awaits the assigned DM’s approval.':'Change saved and recorded.');}catch(err){const message=$('actionMessage');message.textContent=err.message;message.scrollIntoView?.({block:'nearest',behavior:'smooth'});}finally{form.dataset.saving='false';if(kind==='sync'){form.dataset.uploading='false';renderSelectedDocuments(form);}buttons.forEach((b,i)=>b.disabled=disabled[i]);if(btn)btn.textContent=buttonLabel;}}

async function loadActivity(){try{return await allRows('/rest/v1/rpc/occci_activity');}catch(err){if(!err.message.includes('Workflow database setup is pending'))throw err;return allRows('/rest/v1/occci_audit?select=*&order=created_at.desc,id.desc');}}
const OAUTH_KEY='occci.google.pkce.v1';
function base64url(bytes){return btoa(String.fromCharCode(...bytes)).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');}
async function googleSignIn(btn){btn.disabled=true;try{const settings=await api('/auth/v1/settings',{auth:false});if(!settings.external?.google)throw Error('Google sign-in is awaiting cooperative activation. Please use email sign-in for now.');
 const check=await fetch(C.url+'/rest/v1/occci_profiles?select=onboarding_complete&limit=0',{headers:{apikey:C.publishableKey},cache:'no-store'});const result=await check.json();if(!check.ok&&result.code!=='42501')throw Error('Google registration is awaiting cooperative setup. Please use email sign-in for now.');
 const verifier=base64url(crypto.getRandomValues(new Uint8Array(32))),challenge=base64url(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(verifier))));sessionStorage.setItem(OAUTH_KEY,JSON.stringify({verifier,created:Date.now()}));
 const url=new URL(C.url+'/auth/v1/authorize');url.search=new URLSearchParams({provider:'google',redirect_to:window.location.origin+'/',code_challenge:challenge,code_challenge_method:'s256'});window.location.assign(url.href);
 }catch(err){S.error=err.message;render();}finally{btn.disabled=false;}}
async function finishGoogleSignIn(){const url=new URL(window.location.href),code=url.searchParams.get('code'),error=url.searchParams.get('error_description')||url.searchParams.get('error');if(!code&&!error)return;let flow;try{flow=JSON.parse(sessionStorage.getItem(OAUTH_KEY)||'null');}catch{}sessionStorage.removeItem(OAUTH_KEY);for(const key of ['code','error','error_description','error_code'])url.searchParams.delete(key);window.history.replaceState(null,'',url.pathname+url.search+url.hash);
 if(error)throw Error('Google sign-in was not completed. Please try again.');if(!flow?.verifier||Date.now()-flow.created>10*60*1000)throw Error('Google sign-in expired or opened in a different browser. Start again on this device.');
 const result=await api('/auth/v1/token?grant_type=pkce',{method:'POST',auth:false,data:{auth_code:code,code_verifier:flow.verifier}});storeSession({...result,expires_at:Date.now()/1000+result.expires_in});S.page='Home';}
function onboardingView(){return heading('Complete your profile','Choose your district and branch, enter your details, and select an avatar.')+`<section class="card auth-card"><form onsubmit="event.preventDefault();completeOnboarding(this)"><div class="form-grid">${memberProfileFields()}</div><p class="smalltext">Your email is verified. Your branch will verify your cooperative membership.</p><button type="submit" class="primary">Save and continue</button><p id="authMessage" role="status" aria-live="polite"></p></form></section>`;}
async function completeOnboarding(form){const btn=form.querySelector('[type=submit]');btn.disabled=true;try{const f=new FormData(form),data=Object.fromEntries(f);delete data.photo;await rpc('occci_complete_onboarding',{values_json:data});await reload();if(isStaff())S.page='Overview';render();const file=f.get('photo');if(file?.size){try{await uploadPhotoBlob(await normalizePhoto(file));}catch(err){toast('Profile saved. '+err.message);}}}catch(err){const node=$('authMessage');if(node)node.textContent=err.message;else toast(err.message);}finally{btn.disabled=false;}}

async function init(){restoreStaffInvite();window.addEventListener('hashchange',staffInviteHashChanged);try{const s=JSON.parse(localStorage.getItem(SESSION_KEY)||'null');if(s?.access_token&&s?.refresh_token)S.session=s;}catch{}try{await loadBranches();await finishStaffSignup();await finishGoogleSignIn();await restoreStaffCode();}catch(err){S.error=err.message;}if(S.session)await reload();else render();if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js').catch(()=>{});}
init();
